// On a Lovable preview surface, broker the auth session to the editor over
// postMessage so the project's preview surfaces share one login; else localStorage.
export function brokeredPreviewStorage() {
  if (typeof window === 'undefined') return undefined;
  const host = location.hostname;
  const PREVIEW_ZONES = ['lovableproject.com', 'lovableproject-dev.com', 'lovable.app', 'gpt-eng.com', 'gptengineer.run'];
  const onPreviewZone = PREVIEW_ZONES.some((z) => host === z || host.endsWith('.' + z));
  // Read the id only from non-user-controlled host positions, so a user-named
  // preview--<name> host can't smuggle another project's id.
  const UUID = '[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}';
  const projectId = onPreviewZone
    ? (host.match(new RegExp('^(?:id-preview(?:-[a-z0-9]+)?|project)--(' + UUID + ')(?:-dev)?(?=\\.|$)', 'i'))?.[1]
        ?? host.match(new RegExp('^(' + UUID + ')(?=[.-])', 'i'))?.[1])
    : undefined;
  const framed = window.parent && window.parent !== window;
  if (!projectId || !framed) return localStorage;

  // Post only to the real editor ancestor, validated as a Lovable origin, so the
  // session token can never reach an untrusted embedder.
  const dev = host.endsWith('.lovableproject-dev.com') || host.endsWith('.gpt-eng.com');
  const EDITOR = dev
    ? /^https:\/\/([a-z0-9-]+\.)*(lovable\.dev|gptengineer\.app)$|^http:\/\/localhost:3000$/
    : /^https:\/\/([a-z0-9-]+\.)*(lovable\.dev|gptengineer\.app)$/;
  const ancestor = (location.ancestorOrigins && location.ancestorOrigins[0]) || (document.referrer ? new URL(document.referrer).origin : '');
  const editorOrigins = ancestor && EDITOR.test(ancestor)
    ? [ancestor]
    : (dev ? ['https://lovable.dev', 'http://localhost:3000'] : ['https://lovable.dev']);
  const RESULT = 'lovable-preview-auth:result';
  const TIMEOUT = 2000;
  const newId = () => Math.random().toString(36).slice(2) + Date.now().toString(36);

  const request = (type: string, key: string, value?: string): Promise<{ ok: boolean; value?: string | null } | null> =>
    new Promise((resolve) => {
      const requestId = newId();
      let done = false;
      let timer: ReturnType<typeof setTimeout>;
      const finish = (r: { ok: boolean; value?: string | null } | null) => {
        if (done) return;
        done = true;
        clearTimeout(timer);
        window.removeEventListener('message', onMessage);
        resolve(r);
      };
      const onMessage = (e: MessageEvent) => {
        if (editorOrigins.indexOf(e.origin) < 0) return;
        const d = e.data;
        if (d && d.type === RESULT && d.requestId === requestId) finish(d);
      };
      window.addEventListener('message', onMessage);
      const msg: Record<string, unknown> = { type, requestId, projectId, key };
      if (value !== undefined) msg['value'] = value;
      // targetOrigin per trusted editor origin, so a session token never reaches an arbitrary embedder.
      for (const origin of editorOrigins) window.parent.postMessage(msg, origin);
      timer = setTimeout(() => finish(null), TIMEOUT);
    });

  // The editor may not be listening yet at the first getItem, so retry once.
  let firstGet = true;
  const RETRY_DELAY = 250;

  return {
    getItem: async (key: string) => {
      let res = await request('lovable-preview-auth:get', key);
      if (!res && firstGet) {
        await new Promise((r) => setTimeout(r, RETRY_DELAY));
        res = await request('lovable-preview-auth:get', key);
      }
      firstGet = false;
      // '' is the logout tombstone: clear the local copy too so it can't resurrect if
      // the broker later goes silent. A null reply means never-synced -> keep local.
      if (res && res.ok && typeof res.value === 'string') {
        if (res.value === '') { localStorage.removeItem(key); return null; }
        return res.value;
      }
      return localStorage.getItem(key);
    },
    setItem: (key: string, value: string) => {
      localStorage.setItem(key, value);
      return request('lovable-preview-auth:set', key, value).then(() => undefined);
    },
    removeItem: (key: string) => {
      localStorage.removeItem(key);
      return request('lovable-preview-auth:remove', key).then(() => undefined);
    },
  };
}

import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";
import { setCookie } from "@tanstack/react-start/server";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";

const Kind = z.enum(["album", "experience"]);

/** Default PIN lifetime. Rotate before this and reprint the card. */
const PIN_TTL_DAYS = 180;
/** QR access tokens outlive PINs — they are cheap to revoke individually. */
const TOKEN_TTL_DAYS = 365;

/* ------------------------------------------------------------------ */
/* Public: manual PIN entry                                            */
/* ------------------------------------------------------------------ */

/**
 * Checks a PIN against the bcrypt hash held in Postgres. Nothing reversible
 * is stored, so even we cannot read a PIN back after it is issued.
 *
 * Rate limited to 5 failures/hour/IP with a 15-minute lockout per slug, and
 * every failure is written to the audit log. The response never discloses
 * attempt counts or lockout timing — except for an expired PIN, where a
 * generic "incorrect" would send the customer down the wrong path.
 */
export const submitAccessPin = createServerFn({ method: "POST" })
  .validator((raw) =>
    z
      .object({
        kind: Kind,
        slug: z.string().min(1).max(120),
        pin: z.string().min(1).max(32),
      })
      .parse(raw),
  )
  .handler(async ({ data }) => {
    const { callerIp, auditPinFailure } = await import("@/lib/content-access.server");
    const { accessCookieName, signAccessCookie, ACCESS_COOKIE_MAX_AGE } =
      await import("@/lib/access.server");
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");

    const ip = callerIp();

    const { data: allowed } = await supabaseAdmin.rpc("pin_attempts_allowed", {
      _slug: data.slug,
      _ip: ip,
    });
    if (allowed === false) {
      return { ok: false as const, reason: "invalid" as const, message: "Incorrect PIN." };
    }

    const { data: result } = await supabaseAdmin.rpc("verify_content_pin", {
      _kind: data.kind,
      _slug: data.slug,
      _pin: data.pin,
    });

    if (result !== "ok") {
      await supabaseAdmin.rpc("pin_record_failure", { _slug: data.slug, _ip: ip });
      await auditPinFailure(data.kind, data.slug, ip);
      if (result === "pin_expired") {
        return {
          ok: false as const,
          reason: "pin_expired" as const,
          message: "This PIN has expired. Ask for a new card or a fresh link.",
        };
      }
      return { ok: false as const, reason: "invalid" as const, message: "Incorrect PIN." };
    }

    await supabaseAdmin.rpc("pin_clear_failures", { _slug: data.slug, _ip: ip });

    const expiresAt = Date.now() + ACCESS_COOKIE_MAX_AGE * 1000;
    setCookie(
      accessCookieName(data.kind, data.slug),
      await signAccessCookie(data.slug, expiresAt),
      {
        httpOnly: true,
        secure: true,
        sameSite: "lax",
        path: "/",
        maxAge: ACCESS_COOKIE_MAX_AGE,
      },
    );

    return { ok: true as const, reason: "ok" as const };
  });

/* ------------------------------------------------------------------ */
/* Admin/owner: issue + rotate credentials                             */
/* ------------------------------------------------------------------ */

async function loadOwnedRow(supabase: any, kind: "album" | "experience", id: string) {
  const table = kind === "album" ? "albums" : "ar_experiences";
  const { data, error } = await supabase
    .from(table)
    .select("id, slug, title, access_mode, pin_created_at, pin_expires_at")
    .eq("id", id)
    .maybeSingle();
  if (error) throw new Error(error.message);
  if (!data) throw new Response("Forbidden", { status: 403 });
  return data;
}

/** Mints a fresh PIN + QR access token for a row the caller owns. */
async function issueCredentials(kind: "album" | "experience", id: string) {
  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");

  // PIN is generated in Postgres with gen_random_bytes + rejection sampling.
  const { data: pin, error: genErr } = await supabaseAdmin.rpc("generate_content_pin", {
    _length: 6,
  });
  if (genErr) throw new Error(genErr.message);

  const { data: pinExpires, error: setErr } = await supabaseAdmin.rpc("set_content_pin", {
    _kind: kind,
    _id: id,
    _pin: pin as string,
    _ttl_days: PIN_TTL_DAYS,
  });
  if (setErr) throw new Error(setErr.message);

  // Old printed QR codes stop working the moment credentials are re-issued.
  await supabaseAdmin.rpc("revoke_content_access_tokens", {
    _kind: kind,
    _content_id: id,
  });

  const { data: tok, error: tokErr } = await supabaseAdmin.rpc("issue_content_access_token", {
    _kind: kind,
    _content_id: id,
    _ttl_days: TOKEN_TTL_DAYS,
    _label: "printed-qr",
  });
  if (tokErr) throw new Error(tokErr.message);

  return { pin: pin as string, tok: tok as string, pinExpiresAt: pinExpires as string };
}

/**
 * Share state for the owner. The PIN is NOT returned here — it only exists in
 * plaintext at the moment it is issued. Reprinting requires re-issuing.
 */
export const getShareCredentials = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ kind: Kind, id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const row = await loadOwnedRow(context.supabase, data.kind, data.id);
    return {
      slug: row.slug as string,
      title: row.title as string,
      restricted: row.access_mode === "restricted",
      pin: null as string | null,
      tok: null as string | null,
      pinExpiresAt: (row.pin_expires_at ?? null) as string | null,
    };
  });

/**
 * Switches content between public and restricted.
 * Going restricted mints a fresh 12-16 char slug, a fresh PIN and a fresh QR
 * token, so the old public URL stops resolving. Going public wipes the PIN
 * and revokes every outstanding QR token.
 */
export const setAccessMode = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) =>
    z
      .object({ kind: Kind, id: z.string().uuid(), mode: z.enum(["public", "restricted"]) })
      .parse(raw),
  )
  .handler(async ({ data, context }) => {
    const row = await loadOwnedRow(context.supabase, data.kind, data.id);
    const table = data.kind === "album" ? "albums" : "ar_experiences";
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");

    if (data.mode === "public") {
      const { error } = await context.supabase
        .from(table)
        .update({
          access_mode: "public",
          pin_hash: null,
          pin_created_at: null,
          pin_expires_at: null,
          pin_updated_at: null,
        })
        .eq("id", data.id);
      if (error) throw new Error(error.message);
      await supabaseAdmin.rpc("revoke_content_access_tokens", {
        _kind: data.kind,
        _content_id: data.id,
      });
      return {
        slug: row.slug as string,
        pin: null,
        tok: null,
        pinExpiresAt: null,
        restricted: false as const,
      };
    }

    const { generateRestrictedSlug } = await import("@/lib/access.server");
    const slug = generateRestrictedSlug();

    const { error } = await context.supabase
      .from(table)
      .update({ access_mode: "restricted", slug, show_in_gallery: false })
      .eq("id", data.id);
    if (error) throw new Error(error.message);

    const issued = await issueCredentials(data.kind, data.id);
    return { slug, ...issued, restricted: true as const };
  });

/**
 * Rotates the PIN and the QR token together — every previously printed card
 * stops working immediately. This is also the only way to see a PIN again,
 * because nothing reversible is stored.
 */
export const regeneratePin = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ kind: Kind, id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const row = await loadOwnedRow(context.supabase, data.kind, data.id);
    if (row.access_mode !== "restricted") throw new Error("Content is not restricted");

    const issued = await issueCredentials(data.kind, data.id);

    await context.supabase.from("audit_log").insert({
      actor_id: context.userId,
      action: "pin.regenerated",
      target_type: data.kind,
      target_id: row.slug,
    });

    return { slug: row.slug as string, ...issued, restricted: true as const };
  });

import { createServerFn } from "@tanstack/react-start";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";

/**
 * Self-scoped account read (own profile + own licence, if the deployment has
 * a licences table at all).
 *
 * This lives outside the admin approvals module on purpose: that module
 * is admin/issuer-only and is stripped from customer (client-app) deliveries,
 * but the holding page at /pending still has to work there.
 */
export const getMyAccount = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }) => {
    const { data: profile, error } = await context.supabase
      .from("profiles")
      .select("id, display_name, email, approval_status, approval_decided_at, rejection_reason")
      .eq("id", context.userId)
      .maybeSingle();
    if (error) throw new Error(error.message);

    // Client-app builds have no licences table; a failure here is not fatal.
    let license: unknown = null;
    try {
      const { data } = await context.supabase
        .from("licenses")
        .select("license_key, plan, status, max_activations, issued_at, expires_at")
        .eq("owner_user_id", context.userId)
        .maybeSingle();
      license = data ?? null;
    } catch {
      license = null;
    }

    return { profile: profile ?? null, license: license as Record<string, any> | null };
  });

/**
 * Licence adapter — CLIENT side. This is the ONLY licence module that exists on
 * the `client-app` branch. It can verify and refresh; it can never issue.
 *
 * Configuration a customer touches:
 *   VITE_LICENCE_API_URL      your admin server
 *   VITE_LICENCE_KEY          the key you sold them
 *   VITE_LICENCE_PUBLIC_KEY   Ed25519 public JWK, baked at build time
 */
const STORAGE_TOKEN = "aether.licence.token";
const STORAGE_INSTALL = "aether.install.uuid";
const STORAGE_LAST_OK = "aether.licence.lastOk";
/** Server-minted device identity. The fingerprint is only a support signal. */
const STORAGE_DEVICE_SECRET = "aether.licence.deviceSecret";
const REFRESH_EVERY_MS = 12 * 60 * 60 * 1000; // 12h
/**
 * §4.5 Grace hours — reduced from 72h to 24h.
 * A cracked deployment now goes dark within one day without a server check-in.
 * The server can override this per-licence via the JWT `grace` claim.
 * Env: VITE_LICENCE_GRACE_HOURS (optional, integer, max 48).
 */
const _envGrace = parseInt(
  (import.meta.env as Record<string, string>)["VITE_LICENCE_GRACE_HOURS"] ?? "",
  10,
);
const DEFAULT_GRACE_HOURS = Number.isFinite(_envGrace) && _envGrace > 0 ? Math.min(_envGrace, 48) : 24;

export interface LicencePayload {
  sub: string;
  dep?: string;
  did?: string;
  jti?: string;
  device?: string;
  platform: "mobile" | "desktop";
  plan: string;
  features: string[];
  grace?: number;
  iat: number;
  exp: number;
}

export interface LicenceState {
  status: "valid" | "grace" | "invalid" | "unconfigured";
  payload: LicencePayload | null;
  error?: string;
  graceEndsAt?: number;
}

function envVar(name: string): string | undefined {
  return (import.meta.env as Record<string, string | undefined>)[name];
}

/**
 * Build integrity check — runs once at module load on the client-app branch.
 * Ensures VITE_CUSTOMER_ID, VITE_BUILD_ID, and VITE_RELEASE_HASH are present
 * and non-placeholder. If missing, the app renders in a locked state.
 * This is NOT a security gate (JS is client-side) but it prevents accidental
 * deployments of un-provisioned builds and catches mis-configurations early.
 */
export function buildIntegrityOk(): boolean {
  const customerId = envVar("VITE_CUSTOMER_ID");
  const buildId = envVar("VITE_BUILD_ID");
  const releaseHash = envVar("VITE_RELEASE_HASH");
  // Placeholders that provision-client.mjs replaces at generation time
  const PLACEHOLDERS = ["", "REPLACE_ME", "YOUR_CUSTOMER_ID", "undefined", "null"];
  if (!customerId || PLACEHOLDERS.includes(customerId)) return false;
  if (!buildId || PLACEHOLDERS.includes(buildId)) return false;
  // release hash is optional in dev but required in production
  if (envVar("VITE_NODE_ENV") === "production") {
    if (!releaseHash || PLACEHOLDERS.includes(releaseHash)) return false;
  }
  return true;
}

export function isLicenceEnforced() {
  return Boolean(envVar("VITE_LICENCE_API_URL") && envVar("VITE_LICENCE_KEY"));
}

export function deviceClass(): "mobile" | "desktop" {
  if (typeof navigator === "undefined") return "desktop";
  return /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent) ? "mobile" : "desktop";
}

function installUuid() {
  let id = localStorage.getItem(STORAGE_INSTALL);
  if (!id) {
    id = crypto.randomUUID();
    localStorage.setItem(STORAGE_INSTALL, id);
  }
  return id;
}

async function sha256Hex(input: string) {
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(input));
  return Array.from(new Uint8Array(buf))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

/**
 * Fingerprints are spoofable — treat them as friction, not proof. The real
 * teeth are that assets only presign against a valid server-side licence.
 */
export async function deviceFingerprint() {
  const parts = [
    navigator.userAgent,
    navigator.language,
    String(screen.width),
    String(screen.height),
    String(new Date().getTimezoneOffset()),
    String(navigator.hardwareConcurrency ?? 0),
    installUuid(),
  ];
  return sha256Hex(parts.join("|"));
}

/**
 * Mirror the signed token into a cookie so SSR loaders and server functions
 * can gate presigning on it (§4.7). The cookie carries no secret — it is the
 * same publicly verifiable token — and the device secret never leaves
 * localStorage.
 */
const LICENCE_COOKIE = "aether_licence";

function writeLicenceCookie(token: string) {
  if (typeof document === "undefined") return;
  const secure = location.protocol === "https:" ? "; secure" : "";
  document.cookie = `${LICENCE_COOKIE}=${token}; path=/; max-age=86400; samesite=lax${secure}`;
}

function clearLicenceCookie() {
  if (typeof document === "undefined") return;
  document.cookie = `${LICENCE_COOKIE}=; path=/; max-age=0; samesite=lax`;
}

function decode(token: string): LicencePayload | null {
  try {
    const body = token.split(".")[1];
    if (!body) return null;
    const json = atob(body.replace(/-/g, "+").replace(/_/g, "/"));
    return JSON.parse(json) as LicencePayload;
  } catch {
    return null;
  }
}

function b64ToBytes(b64: string) {
  const bin = atob(b64.replace(/-/g, "+").replace(/_/g, "/"));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

async function verifySignature(token: string): Promise<boolean> {
  const jwkRaw = envVar("VITE_LICENCE_PUBLIC_KEY");
  if (!jwkRaw) return false;
  const [header, body, sig] = token.split(".");
  if (!header || !body || !sig) return false;
  try {
    const key = await crypto.subtle.importKey(
      "jwk",
      JSON.parse(jwkRaw) as JsonWebKey,
      { name: "Ed25519" },
      false,
      ["verify"],
    );
    return crypto.subtle.verify(
      "Ed25519",
      key,
      b64ToBytes(sig),
      new TextEncoder().encode(`${header}.${body}`),
    );
  } catch {
    return false;
  }
}

interface LicenceApiResult {
  token: string;
  plan: string;
  features: string[];
  graceHours?: number;
  deviceId?: string;
  deviceSecret?: string;
}

async function callLicenceApi(
  path: string,
  body: Record<string, unknown>,
): Promise<LicenceApiResult> {
  const base = envVar("VITE_LICENCE_API_URL")!.replace(/\/+$/, "");
  const res = await fetch(`${base}${path}`, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
  const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
  if (!res.ok || json["ok"] !== true) {
    throw new Error(String(json["error"] ?? `licence_api_${res.status}`));
  }
  return json as unknown as LicenceApiResult;
}

async function attest() {
  const { buildAttestation } = await import("./integrity-runtime");
  return buildAttestation();
}

function deviceSecret() {
  return localStorage.getItem(STORAGE_DEVICE_SECRET);
}

/** Rough capability hint so the AR runtime can pick a perf tier server-side. */
function capabilityTier(): string {
  const cores = navigator.hardwareConcurrency ?? 4;
  const mem = (navigator as unknown as { deviceMemory?: number }).deviceMemory ?? 4;
  if (cores <= 4 || mem <= 3) return "lite";
  if (cores >= 8 && mem >= 8) return "high";
  return "standard";
}

/** Activate or refresh, returning the current enforcement state. */
export async function ensureLicence(): Promise<LicenceState> {
  if (!isLicenceEnforced()) return { status: "unconfigured", payload: null };

  const cached = localStorage.getItem(STORAGE_TOKEN);
  const cachedPayload = cached ? decode(cached) : null;
  const now = Math.floor(Date.now() / 1000);
  const stillFresh = cachedPayload && cachedPayload.exp - now > 24 * 3600 - REFRESH_EVERY_MS / 1000;

  if (cached && stillFresh && (await verifySignature(cached))) {
    localStorage.setItem(STORAGE_LAST_OK, String(Date.now()));
    writeLicenceCookie(cached);
    return { status: "valid", payload: cachedPayload };
  }

  const secret = deviceSecret();
  try {
    const attestation = await attest();
    // Refresh only once the server has minted a device identity for us.
    const path = secret ? "/api/public/licence/refresh" : "/api/public/licence/activate";
    const result = await callLicenceApi(path, {
      licenceKey: envVar("VITE_LICENCE_KEY"),
      platform: deviceClass(),
      deviceFingerprint: await deviceFingerprint(),
      capabilityTier: capabilityTier(),
      ...(secret ? { deviceSecret: secret } : {}),
      ...attestation,
    });
    if (!(await verifySignature(result.token))) {
      return { status: "invalid", payload: null, error: "BAD_SIGNATURE" };
    }
    if (result.deviceSecret) {
      localStorage.setItem(STORAGE_DEVICE_SECRET, result.deviceSecret);
    }
    localStorage.setItem(STORAGE_TOKEN, result.token);
    localStorage.setItem(STORAGE_LAST_OK, String(Date.now()));
    writeLicenceCookie(result.token);
    return { status: "valid", payload: decode(result.token) };
  } catch (e) {
    const error = e instanceof Error ? e.message : "licence_unreachable";
    const hardFail = [
      "DEVICE_LIMIT",
      "DEVICE_UNKNOWN",
      "DEVICE_CLASS_MISMATCH",
      "ATTESTATION_INVALID",
      "ORIGIN_NOT_ALLOWED",
      "LICENCE_SUSPENDED",
      "LICENCE_REVOKED",
      "LICENCE_EXPIRED",
      "INVALID_LICENCE",
    ];
    if (hardFail.includes(error)) {
      localStorage.removeItem(STORAGE_TOKEN);
      clearLicenceCookie();
      return { status: "invalid", payload: null, error };
    }

    // Offline grace is anchored to the SIGNED token's `exp` + `graceHours`,
    // not to a local "last ok" timestamp — preventing client-side clock/storage tampering.
    if (cachedPayload && (await verifySignature(cached!))) {
      const graceHours = cachedPayload.grace ?? DEFAULT_GRACE_HOURS;
      const graceEndsAt = (cachedPayload.exp + graceHours * 3600) * 1000;
      if (Date.now() < graceEndsAt) {
        return { status: "grace", payload: cachedPayload, error, graceEndsAt };
      }
    }
    // If exp + graceHours has passed, refuse cached token, clear storage and cookie immediately
    localStorage.removeItem(STORAGE_TOKEN);
    clearLicenceCookie();
    return { status: "invalid", payload: null, error: "GRACE_EXPIRED" };
  }
}

/** Hand the device slot back so another machine can activate (§4.4). */
export async function releaseThisDevice() {
  const secret = deviceSecret();
  if (!secret) return { ok: false, error: "NO_DEVICE" as const };
  try {
    const base = envVar("VITE_LICENCE_API_URL")!.replace(/\/+$/, "");
    const res = await fetch(`${base}/api/public/licence/release`, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ licenceKey: envVar("VITE_LICENCE_KEY"), deviceSecret: secret }),
    });
    const json = (await res.json().catch(() => ({}))) as Record<string, unknown>;
    if (!res.ok || json["ok"] !== true) {
      return { ok: false as const, error: String(json["error"] ?? `licence_api_${res.status}`) };
    }
    localStorage.removeItem(STORAGE_DEVICE_SECRET);
    localStorage.removeItem(STORAGE_TOKEN);
    clearLicenceCookie();
    localStorage.removeItem(STORAGE_LAST_OK);
    return { ok: true as const, releaseAfter: String(json["releaseAfter"] ?? "") };
  } catch (e) {
    return { ok: false as const, error: e instanceof Error ? e.message : "release_failed" };
  }
}

/** Background refresh loop — call once from the app root. */
export function startLicenceHeartbeat() {
  if (!isLicenceEnforced()) return () => {};
  void ensureLicence();
  const id = setInterval(() => void ensureLicence(), REFRESH_EVERY_MS);
  return () => clearInterval(id);
}

export function currentToken() {
  return localStorage.getItem(STORAGE_TOKEN);
}

/**
 * Licence adapter — ISSUER side. Exists on `main` and `self-hosted` ONLY.
 * It must never ship on `client-release`: if the customer hosts the validator,
 * they own the validator and every control below is theatre.
 *
 * Design rule (see the commercial blueprint §0): this layer is NOT DRM. Its job
 * is attribution and provenance — make a resold deployment detectable and
 * attributable. The one control with real teeth is presign gating (§4.7): media
 * lives in a bucket with no public read policy, so a licence that does not
 * verify simply never gets a URL.
 *
 * Hard rules encoded here:
 *   §4.1 absent/unparseable attestation is INVALID, never "skip".
 *   §4.2 origin and device identity are server-derived, never body-supplied.
 *   §4.3 one live mobile + one live desktop, enforced by a unique partial index.
 *   §4.4 self-service release with a 12h cooldown.
 *   §4.5 24h EdDSA tokens carrying their own 72h grace window.
 *   §4.8 high-severity violations email the admin, deduped per kind per 24h.
 */
import { readEnv, requireEnv } from "./env.server";
import { sendMail } from "./mailer.server";
import { escapeHtml } from "@/lib/notify.server";

export type DeviceClass = "mobile" | "desktop";

/** Attestation as it arrives from the client. Never trusted, always verified. */
export interface Attestation {
  buildId?: unknown;
  assetDigest?: unknown;
}

/**
 * Everything the issuer needs. `originHost` and `ip` are filled in by the route
 * from request headers — callers must not accept them from the request body.
 */
export interface ActivateInput {
  licenceKey: string;
  platform: DeviceClass;
  /** Server-derived from Origin/Host. */
  originHost: string | null;
  ip: string | null;
  userAgent?: string | null;
  attestation: Attestation;
  /** Client-computed. Stored as a support signal only — never an identity. */
  fingerprintSignal?: string | null;
  /** Returned once at activation; proves possession on later calls. */
  deviceSecret?: string | null;
  capabilityTier?: string | null;
  label?: string | null;
}

export interface IssuedLicence {
  token: string;
  expiresIn: number;
  graceHours: number;
  plan: string;
  features: string[];
  deviceId: string;
  /** Present only on first activation of a device. Never retrievable again. */
  deviceSecret?: string;
}

const TOKEN_TTL_SEC = 60 * 60 * 24; // 24h
/**
 * §4.5 Grace hours — reduced from 72h to 24h.
 * Override per-deployment via LICENCE_GRACE_HOURS env var (max 48).
 * The value is embedded in the issued JWT so the client uses the
 * server's authoritative setting, not its own default.
 */
const _cfgGrace = parseInt(process.env.LICENCE_GRACE_HOURS ?? "", 10);
const GRACE_HOURS = Number.isFinite(_cfgGrace) && _cfgGrace > 0 ? Math.min(_cfgGrace, 48) : 24; // §4.5
const RELEASE_COOLDOWN_HOURS = 12; // §4.4
const NOTIFY_DEDUP_HOURS = 24; // §4.8
const enc = new TextEncoder();

/* ------------------------------------------------------------------ crypto */

function b64url(bytes: Uint8Array | string) {
  const str = typeof bytes === "string" ? bytes : String.fromCharCode(...Array.from(bytes));
  return btoa(str).replace(/=+$/g, "").replace(/\+/g, "-").replace(/\//g, "_");
}

function randomSecret() {
  return b64url(crypto.getRandomValues(new Uint8Array(32)));
}

async function sha256Hex(value: string) {
  const buf = await crypto.subtle.digest("SHA-256", enc.encode(value));
  return Array.from(new Uint8Array(buf))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");
}

function timingSafeEqual(a: string, b: string) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

async function signToken(payload: Record<string, unknown>) {
  const jwk = JSON.parse(requireEnv("LICENCE_PRIVATE_KEY_JWK")) as JsonWebKey;
  const key = await crypto.subtle.importKey("jwk", jwk, { name: "Ed25519" }, false, ["sign"]);
  const header = b64url(JSON.stringify({ alg: "EdDSA", typ: "JWT" }));
  const body = b64url(JSON.stringify(payload));
  const sig = new Uint8Array(
    await crypto.subtle.sign("Ed25519", key, enc.encode(`${header}.${body}`)),
  );
  return `${header}.${body}.${b64url(sig)}`;
}

async function admin() {
  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  return supabaseAdmin;
}

/* -------------------------------------------------------------- violations */

type Severity = "low" | "medium" | "high" | "critical";

const SEVERITY: Record<string, Severity> = {
  missing_attestation: "high",
  unsigned_build: "high",
  unknown_build: "high",
  digest_mismatch: "critical",
  origin_not_allowed: "high",
  origins_not_configured: "high",
  device_limit: "high",
  device_secret_mismatch: "critical",
  duplicate_deployment: "critical",
  release_cooldown: "low",
};

export async function recordViolation(
  kind: string,
  detail: Record<string, unknown>,
  ctx: {
    licenseId?: string | null;
    licenceKey?: string;
    fingerprint?: string | null;
    originHost?: string | null;
    ip?: string | null;
  },
  opts: { suspend?: boolean } = {},
) {
  const db = await admin();
  const severity = SEVERITY[kind] ?? "medium";

  const { data: inserted } = await db
    .from("license_violations")
    .insert({
      license_id: ctx.licenseId ?? null,
      license_key: ctx.licenceKey ?? null,
      kind,
      severity,
      detail: detail as never,
      fingerprint: ctx.fingerprint ?? null,
      origin_host: ctx.originHost ?? null,
      ip_address: ctx.ip ?? null,
    })
    .select("id")
    .maybeSingle();

  if (opts.suspend && ctx.licenseId) {
    await db.from("licenses").update({ status: "suspended" }).eq("id", ctx.licenseId);
  }

  if (severity !== "high" && severity !== "critical") return;

  // §4.8 — at most one email per (licence, kind) per 24h.
  const since = new Date(Date.now() - NOTIFY_DEDUP_HOURS * 3600_000).toISOString();
  const { count } = await db
    .from("license_violations")
    .select("id", { count: "exact", head: true })
    .eq("kind", kind)
    .eq("license_id", ctx.licenseId ?? "00000000-0000-0000-0000-000000000000")
    .gt("notified_at", since);
  if ((count ?? 0) > 0) return;

  const to = readEnv("ALERT_TO_EMAIL");
  if (!to) return;
  const rows = Object.entries({ ...ctx, ...detail, severity, suspended: !!opts.suspend })
    .map(([k, v]) => `<tr><td><b>${escapeHtml(k)}</b></td><td>${escapeHtml(v)}</td></tr>`)
    .join("");
  const sent = await sendMail({
    to,
    subject: `[${severity}] Licence violation — ${kind}`,
    html: `<p>A licence violation was recorded.</p><table>${rows}</table>
           <p><a href="${escapeHtml(readEnv("ADMIN_BASE_URL") ?? "")}/dashboard/activations">Open the admin dashboard</a></p>`,
  });
  if (sent && inserted?.id) {
    await db
      .from("license_violations")
      .update({ notified_at: new Date().toISOString() })
      .eq("id", inserted.id);
  }
}

/* ------------------------------------------------------------- attestation */

/**
 * §4.1 — a discriminated union so a new state cannot silently fall through to
 * "allow". Callers must handle every case; the default branch denies.
 */
type Attested =
  | { kind: "ok"; buildId: string; assetDigest: string }
  | { kind: "missing_attestation" }
  | { kind: "unsigned_build" }
  | { kind: "unknown_build"; buildId: string }
  | { kind: "revoked_build"; buildId: string; reason: string }
  | { kind: "digest_mismatch"; buildId: string; reported: string; expected: string };

async function verifyAttestation(a: Attestation): Promise<Attested> {
  const buildId = typeof a.buildId === "string" ? a.buildId.trim() : "";
  const assetDigest = typeof a.assetDigest === "string" ? a.assetDigest.trim() : "";
  if (!buildId || !assetDigest) return { kind: "missing_attestation" };

  const db = await admin();

  // 1. Server-side kill-switch: check if build has been explicitly revoked
  const { data: revoked } = await db
    .from("revoked_builds")
    .select("build_id, reason")
    .eq("build_id", buildId)
    .maybeSingle();

  if (revoked) {
    return { kind: "revoked_build", buildId, reason: revoked.reason };
  }

  // 2. Check signed release manifests
  const { data } = await db
    .from("release_manifests")
    .select("asset_digest, signature")
    .eq("build_id", buildId)
    .maybeSingle();

  if (!data) return { kind: "unknown_build", buildId };
  if (!data.signature || data.signature === "unsigned") return { kind: "unsigned_build" };
  if (data.asset_digest !== assetDigest)
    return { kind: "digest_mismatch", buildId, reported: assetDigest, expected: data.asset_digest };
  return { kind: "ok", buildId, assetDigest };
}

/** Exactly one place decides whether a build may proceed. Default: deny. */
function attestationAllows(a: Attested): boolean {
  switch (a.kind) {
    case "ok":
      return true;
    case "missing_attestation":
    case "unsigned_build":
    case "unknown_build":
    case "revoked_build":
    case "digest_mismatch":
      return false;
    default: {
      const _exhaustive: never = a;
      void _exhaustive;
      return false;
    }
  }
}

/* ------------------------------------------------------------------ origin */

function originAllowed(allowed: string[] | null, host: string | null) {
  // Deny-by-default: an unconfigured licence (no allowed_origins set) must
  // not accept activations from any origin. An admin must explicitly allow
  // at least one origin before the licence can be used in production.
  // This prevents newly-created licences from being exploited before setup.
  if (!allowed || allowed.length === 0) return false;
  if (!host) return false;
  const h = host.toLowerCase().replace(/:\d+$/, "");
  return allowed.some((a) => {
    const want = a
      .toLowerCase()
      .replace(/^https?:\/\//, "")
      .replace(/\/.*$/, "")
      .replace(/:\d+$/, "");
    return h === want || h.endsWith(`.${want}`);
  });
}

/* ------------------------------------------------------------------ tokens */

function getEffectiveGraceHours(override?: number | null): number {
  if (typeof override === "number" && override > 0) return Math.min(override, 168); // Max 7 days for special event override
  const envVal = parseInt(readEnv("LICENCE_GRACE_HOURS") ?? "", 10);
  if (Number.isFinite(envVal) && envVal > 0) return Math.min(envVal, 48);
  return 24; // 24-hour hardened default
}

async function issueToken(
  licence: { id: string; license_key: string; plan: string; grace_hours?: number | null },
  deviceId: string,
  platform: DeviceClass,
) {
  const iat = Math.floor(Date.now() / 1000);
  const features = featuresFor(licence.plan);
  const graceHours = getEffectiveGraceHours(licence.grace_hours);
  const token = await signToken({
    sub: licence.license_key,
    dep: licence.id,
    did: deviceId,
    jti: crypto.randomUUID(),
    platform,
    plan: licence.plan,
    features,
    grace: graceHours,
    iat,
    exp: iat + TOKEN_TTL_SEC,
  });
  return { token, expiresIn: TOKEN_TTL_SEC, graceHours, plan: licence.plan, features };
}

function featuresFor(plan: string): string[] {
  if (plan === "enterprise") return ["ar", "albums", "analytics", "vr", "white_label"];
  if (plan === "pro") return ["ar", "albums", "analytics", "vr"];
  return ["ar", "albums"];
}

/* -------------------------------------------------------------- entrypoint */

type Failure = { ok: false; status: number; error: string };
const fail = (status: number, error: string): Failure => ({ ok: false, status, error });

async function loadLicence(licenceKey: string) {
  const db = await admin();
  const { data } = await db
    .from("licenses")
    .select("id, license_key, plan, status, expires_at, allowed_origins, grace_hours")
    .eq("license_key", licenceKey)
    .maybeSingle();
  return data;
}

type LicenceRow = NonNullable<Awaited<ReturnType<typeof loadLicence>>>;
type ViolationCtx = {
  licenseId: string;
  licenceKey: string;
  fingerprint: string | null;
  originHost: string | null;
  ip: string | null;
};
type Checked =
  | { ok: false; failure: Failure }
  | { ok: true; licence: LicenceRow; ctx: ViolationCtx };

async function commonChecks(input: ActivateInput): Promise<Checked> {
  const licence = await loadLicence(input.licenceKey);
  if (!licence) return { ok: false, failure: fail(404, "INVALID_LICENCE") };
  if (licence.status !== "active")
    return { ok: false, failure: fail(403, `LICENCE_${String(licence.status).toUpperCase()}`) };
  if (licence.expires_at && new Date(licence.expires_at) < new Date())
    return { ok: false, failure: fail(403, "LICENCE_EXPIRED") };

  const ctx: ViolationCtx = {
    licenseId: licence.id,
    licenceKey: input.licenceKey,
    fingerprint: input.fingerprintSignal ?? null,
    originHost: input.originHost,
    ip: input.ip,
  };

  const allowedOrigins = licence.allowed_origins as string[] | null;
  if (!originAllowed(allowedOrigins, input.originHost)) {
    // Separate violation kinds so admins can distinguish "licence was never
    // configured" from "known bad actor using an unlisted origin".
    const violationKind =
      !allowedOrigins || allowedOrigins.length === 0
        ? "origins_not_configured"
        : "origin_not_allowed";
    await recordViolation(
      violationKind,
      { originHost: input.originHost, allowed: allowedOrigins },
      ctx,
    );
    return { ok: false, failure: fail(403, "ORIGIN_NOT_ALLOWED") };
  }

  const attested = await verifyAttestation(input.attestation);
  if (!attestationAllows(attested)) {
    // If build is explicitly revoked, immediately block and collapse grace window to 0
    if (attested.kind === "revoked_build") {
      await recordViolation(
        "build_revoked",
        { buildId: attested.buildId, reason: attested.reason },
        ctx,
        { suspend: true },
      );
      return { ok: false, failure: fail(403, "BUILD_REVOKED") };
    }

    const db = await admin();
    // Soft-fail: log violation and alert admin
    const { count } = await db
      .from("license_violations")
      .select("id", { count: "exact", head: true })
      .eq("license_id", licence.id)
      .eq("kind", "digest_mismatch");

    const mismatchCount = (count ?? 0) + 1;
    const threshold = parseInt(readEnv("INTEGRITY_MISMATCH_THRESHOLD") ?? "3", 10);
    const shouldHardBlock = mismatchCount >= threshold;

    await recordViolation(
      attested.kind === "digest_mismatch" ? "integrity_mismatch" : attested.kind,
      {
        ...attested,
        reportedBuild: input.attestation.buildId,
        mismatchCount,
        threshold,
        softFailAllowed: !shouldHardBlock,
      },
      ctx,
      { suspend: shouldHardBlock },
    );

    // Only hard-block once threshold is exceeded; allows transient CDN cache delays to heal
    if (shouldHardBlock) {
      return { ok: false, failure: fail(403, "ATTESTATION_INVALID") };
    }
  }

  return { ok: true, licence, ctx };
}

export async function activate(
  input: ActivateInput,
): Promise<(IssuedLicence & { ok: true }) | Failure> {
  const checked = await commonChecks(input);
  if (!checked.ok) return checked.failure;
  const { licence, ctx } = checked;
  const db = await admin();
  const now = new Date();

  // Re-activation of a known device: prove possession of the server-minted secret.
  if (input.deviceSecret) {
    const hash = await sha256Hex(input.deviceSecret);
    const { data: rows } = await db
      .from("license_activations")
      .select("id, device_secret_hash, device_class, revoked_at")
      .eq("license_id", licence.id)
      .is("revoked_at", null);
    const match = (rows ?? []).find(
      (r) => r.device_secret_hash && timingSafeEqual(r.device_secret_hash, hash),
    );
    if (match) {
      if (match.device_class !== input.platform) return fail(409, "DEVICE_CLASS_MISMATCH");
      await db
        .from("license_activations")
        .update({
          last_seen_at: now.toISOString(),
          ip_address: input.ip,
          user_agent: input.userAgent ?? null,
          build_id: String(input.attestation.buildId ?? ""),
          asset_digest: String(input.attestation.assetDigest ?? ""),
          origin_host: input.originHost,
          fingerprint: input.fingerprintSignal ?? "",
          capability_tier: input.capabilityTier ?? null,
        })
        .eq("id", match.id);
      const issued = await issueToken(licence, match.id, input.platform);
      return { ok: true as const, ...issued, deviceId: match.id };
    }
    await recordViolation("device_secret_mismatch", { platform: input.platform }, ctx);
    return fail(403, "DEVICE_UNKNOWN");
  }

  // §4.4 — a released slot stays cold for 12h so a licence can't be round-robined.
  const { data: cooling } = await db
    .from("license_activations")
    .select("release_after")
    .eq("license_id", licence.id)
    .eq("device_class", input.platform)
    .not("release_after", "is", null)
    .gt("release_after", now.toISOString())
    .order("release_after", { ascending: false })
    .limit(1)
    .maybeSingle();
  if (cooling?.release_after) {
    await recordViolation("release_cooldown", { until: cooling.release_after }, ctx);
    return fail(423, "RELEASE_COOLDOWN");
  }

  // §4.3 — the unique partial index is the enforcement; this insert is the check.
  const deviceSecret = randomSecret();
  const { data: created, error } = await db
    .from("license_activations")
    .insert({
      license_id: licence.id,
      device_class: input.platform,
      device_secret_hash: await sha256Hex(deviceSecret),
      fingerprint: input.fingerprintSignal ?? "",
      capability_tier: input.capabilityTier ?? null,
      label: input.label ?? null,
      deployment_domain: input.originHost,
      origin_host: input.originHost,
      build_id: String(input.attestation.buildId ?? ""),
      asset_digest: String(input.attestation.assetDigest ?? ""),
      ip_address: input.ip,
      user_agent: input.userAgent ?? null,
      last_seen_at: now.toISOString(),
    })
    .select("id")
    .maybeSingle();

  if (error || !created) {
    // 23505 = the one-live-device-per-class index fired, even under concurrency.
    if ((error as { code?: string } | null)?.code === "23505") {
      await recordViolation("device_limit", { platform: input.platform }, ctx);
      return fail(409, "DEVICE_LIMIT");
    }
    console.error("[licence] activation insert failed", error);
    return fail(500, "ACTIVATION_FAILED");
  }

  const issued = await issueToken(licence, created.id, input.platform);
  return { ok: true as const, ...issued, deviceId: created.id, deviceSecret };
}

/** Heartbeat / refresh. Requires the device secret — no slot allocation here. */
export async function refresh(
  input: ActivateInput,
): Promise<(IssuedLicence & { ok: true }) | Failure> {
  if (!input.deviceSecret) return fail(403, "DEVICE_UNKNOWN");
  const checked = await commonChecks(input);
  if ("failure" in checked) return checked.failure;
  const { licence, ctx } = checked;
  const db = await admin();

  const hash = await sha256Hex(input.deviceSecret);
  const { data: rows } = await db
    .from("license_activations")
    .select("id, device_secret_hash, device_class, revoked_at")
    .eq("license_id", licence.id)
    .is("revoked_at", null);
  const device = (rows ?? []).find(
    (r) => r.device_secret_hash && timingSafeEqual(r.device_secret_hash, hash),
  );
  if (!device) {
    await recordViolation("device_secret_mismatch", { platform: input.platform }, ctx);
    return fail(403, "DEVICE_UNKNOWN");
  }

  await db
    .from("license_activations")
    .update({
      last_seen_at: new Date().toISOString(),
      ip_address: input.ip,
      build_id: String(input.attestation.buildId ?? ""),
      asset_digest: String(input.attestation.assetDigest ?? ""),
      origin_host: input.originHost,
      capability_tier: input.capabilityTier ?? null,
    })
    .eq("id", device.id);

  const issued = await issueToken(licence, device.id, device.device_class as DeviceClass);
  return { ok: true as const, ...issued, deviceId: device.id };
}

/**
 * §4.4 — self-service release. The caller must hold the device secret, so a
 * stranger with only the licence key cannot evict a live device.
 */
export async function releaseDevice(licenceKey: string, deviceSecret: string) {
  const licence = await loadLicence(licenceKey);
  if (!licence) return fail(404, "INVALID_LICENCE");
  const db = await admin();
  const hash = await sha256Hex(deviceSecret);
  const { data: rows } = await db
    .from("license_activations")
    .select("id, device_secret_hash")
    .eq("license_id", licence.id)
    .is("revoked_at", null);
  const device = (rows ?? []).find(
    (r) => r.device_secret_hash && timingSafeEqual(r.device_secret_hash, hash),
  );
  if (!device) return fail(403, "DEVICE_UNKNOWN");

  const now = new Date();
  const releaseAfter = new Date(now.getTime() + RELEASE_COOLDOWN_HOURS * 3600_000);
  await db
    .from("license_activations")
    .update({
      revoked_at: now.toISOString(),
      released_at: now.toISOString(),
      release_after: releaseAfter.toISOString(),
    })
    .eq("id", device.id);
  return { ok: true as const, releaseAfter: releaseAfter.toISOString() };
}

/** Admin override — clears the cooldown immediately (§4.4). */
export async function adminForceRelease(activationId: string) {
  const db = await admin();
  const now = new Date().toISOString();
  await db
    .from("license_activations")
    .update({ revoked_at: now, released_at: now, release_after: null })
    .eq("id", activationId);
  return { ok: true as const };
}

/**
 * Non-sensitive public diagnostic status for client self-service.
 */
export async function getLicenceStatus(licenceKey: string) {
  const licence = await loadLicence(licenceKey);
  if (!licence) return fail(404, "INVALID_LICENCE");

  const db = await admin();
  const { data: activations } = await db
    .from("license_activations")
    .select("device_class, revoked_at, last_seen_at")
    .eq("license_id", licence.id)
    .is("revoked_at", null);

  const active = activations ?? [];
  const mobileCount = active.filter((a) => a.device_class === "mobile").length;
  const desktopCount = active.filter((a) => a.device_class === "desktop").length;

  const allowedOrigins = (licence.allowed_origins as string[] | null) ?? [];

  return {
    ok: true as const,
    status: licence.status,
    plan: licence.plan,
    expiresAt: licence.expires_at,
    deviceSlots: {
      mobile: { used: mobileCount, max: 1 },
      desktop: { used: desktopCount, max: 1 },
    },
    graceHours: licence.grace_hours ?? 24,
    allowedOriginsCount: allowedOrigins.length,
    features: featuresFor(licence.plan),
  };
}

export const __internals = { verifyAttestation, attestationAllows, originAllowed };

/**
 * §4.7 — presign gating. The one licence control with real teeth.
 *
 * Media lives in a bucket with no public read policy, so nothing is delivered
 * without a server-minted signed URL. This module is the single place that
 * decides whether the calling device may get one: it re-verifies the signed
 * licence token, the licence row, the device slot and the build attestation
 * on EVERY presign — uploads and AR runtime asset fetches alike.
 *
 * Fail-closed by design: when enforcement is on, anything unproven is denied.
 * When `LICENCE_ENFORCE_PRESIGN` is not "true" (our own admin deployment,
 * local dev), the gate reports `enforced: false` and allows — enforcement is
 * a deployment decision, never a client-supplied one.
 */
import { getCookie, getRequestHeader } from "@tanstack/react-start/server";
import { readEnv } from "./env.server";

/** Set by the client licence runtime so SSR loaders and serverFns both see it. */
export const LICENCE_COOKIE = "aether_licence";
/** Header alternative for non-browser callers (native shells, tests). */
export const LICENCE_HEADER = "x-aether-licence";

export type PresignPurpose = "upload" | "media_fetch";

export type GateResult =
  | { ok: true; enforced: boolean; deviceId?: string; licenceKey?: string }
  | { ok: false; reason: string; message: string };

/**
 * Enforcement is a deployment decision, never a client-supplied one.
 *
 * It defaults to ON for a customer deployment (`LICENCE_ROLE=client`), so a
 * missing or dropped env var can never silently disable the only control with
 * real teeth. Turning it off there requires an explicit
 * `LICENCE_ENFORCE_PRESIGN=false`. On the issuer deployment (our own admin
 * instance) and in local dev it defaults to OFF.
 */
export function presignGatingEnabled() {
  const raw = (readEnv("LICENCE_ENFORCE_PRESIGN") ?? "").trim().toLowerCase();
  if (raw === "true" || raw === "1") return true;
  if (raw === "false" || raw === "0") return false;
  return (readEnv("LICENCE_ROLE") ?? "issuer").trim().toLowerCase() === "client";
}

interface TokenPayload {
  sub?: string;
  dep?: string;
  did?: string;
  platform?: string;
  plan?: string;
  grace?: number;
  iat?: number;
  exp?: number;
}

function b64ToBytes(b64: string) {
  const bin = atob(b64.replace(/-/g, "+").replace(/_/g, "/"));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

/** Public JWK, either configured directly or derived from the signing key. */
function publicJwk(): JsonWebKey | null {
  const direct = readEnv("LICENCE_PUBLIC_KEY_JWK");
  if (direct) {
    try {
      return JSON.parse(direct) as JsonWebKey;
    } catch {
      return null;
    }
  }
  const priv = readEnv("LICENCE_PRIVATE_KEY_JWK");
  if (!priv) return null;
  try {
    const jwk = JSON.parse(priv) as JsonWebKey & { d?: string };
    const { kty, crv, x } = jwk;
    return { kty, crv, x, key_ops: ["verify"], ext: true } as JsonWebKey;
  } catch {
    return null;
  }
}

async function verifyToken(token: string): Promise<TokenPayload | null> {
  const jwk = publicJwk();
  if (!jwk) return null;
  const [header, body, sig] = token.split(".");
  if (!header || !body || !sig) return null;
  try {
    const key = await crypto.subtle.importKey("jwk", jwk, { name: "Ed25519" }, false, ["verify"]);
    const valid = await crypto.subtle.verify(
      "Ed25519",
      key,
      b64ToBytes(sig) as BufferSource,
      new TextEncoder().encode(`${header}.${body}`),
    );
    if (!valid) return null;
    return JSON.parse(atob(body.replace(/-/g, "+").replace(/_/g, "/"))) as TokenPayload;
  } catch {
    return null;
  }
}

function presentedToken(): string | null {
  const header = getRequestHeader(LICENCE_HEADER);
  if (header) return header.replace(/^Bearer\s+/i, "").trim();
  return getCookie(LICENCE_COOKIE) ?? null;
}

const deny = (reason: string, message: string): GateResult => ({
  ok: false,
  reason,
  message,
});

/**
 * Decide whether this request may be handed a presigned URL.
 * Never throws — callers translate the refusal into their own shape.
 */
export async function checkPresignLicence(
  purpose: PresignPurpose,
  projectId?: string,
): Promise<GateResult> {
  if (!presignGatingEnabled()) return { ok: true, enforced: false };

  const token = presentedToken();
  if (!token) {
    return deny(
      "LICENCE_MISSING",
      "This device has no active licence. Open the app once while online to activate it.",
    );
  }

  const payload = await verifyToken(token);
  if (!payload || !payload.sub) {
    await safeViolation("presign_bad_token", { purpose });
    return deny("LICENCE_INVALID", "This device's licence could not be verified.");
  }

  // Online presign: the 24h token must be live. The 72h offline grace window
  // covers viewing already-loaded state, never minting fresh asset URLs.
  const now = Math.floor(Date.now() / 1000);
  if (!payload.exp || payload.exp < now) {
    return deny(
      "LICENCE_EXPIRED_TOKEN",
      "This device's licence needs to refresh. Reload the page.",
    );
  }

  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");

  const { data: licence } = await supabaseAdmin
    .from("licenses")
    .select("id, license_key, status, expires_at")
    .eq("license_key", payload.sub)
    .maybeSingle();
  if (!licence) {
    await safeViolation("presign_unknown_licence", { purpose, key: payload.sub });
    return deny("INVALID_LICENCE", "This licence is not recognised.");
  }
  if (licence.status !== "active") {
    return deny(
      `LICENCE_${String(licence.status).toUpperCase()}`,
      "This licence is not active. Contact your provider.",
    );
  }
  if (licence.expires_at && new Date(licence.expires_at) < new Date()) {
    return deny("LICENCE_EXPIRED", "This licence has expired.");
  }

  if (!payload.did) {
    await safeViolation("presign_no_device", { purpose }, licence.id, licence.license_key);
    return deny("DEVICE_UNKNOWN", "This device is not registered to the licence.");
  }

  const { data: device } = await supabaseAdmin
    .from("license_activations")
    .select("id, revoked_at, build_id, asset_digest, license_id")
    .eq("id", payload.did)
    .maybeSingle();
  if (!device || device.license_id !== licence.id) {
    await safeViolation("presign_no_device", { purpose }, licence.id, licence.license_key);
    return deny("DEVICE_UNKNOWN", "This device is not registered to the licence.");
  }
  if (device.revoked_at) {
    return deny(
      "DEVICE_RELEASED",
      "This device slot was released. Activate again to keep using the app.",
    );
  }

  // Attestation, re-checked at delivery time: the build this device last
  // reported must still match a signed release manifest. A tampered bundle
  // therefore stops getting media even if its token is still inside 24h.
  const buildId = (device.build_id ?? "").trim();
  const assetDigest = (device.asset_digest ?? "").trim();
  if (!buildId || !assetDigest) {
    await safeViolation(
      "presign_missing_attestation",
      { purpose },
      licence.id,
      licence.license_key,
    );
    return deny("ATTESTATION_INVALID", "This build could not be verified.");
  }
  const { data: manifest } = await supabaseAdmin
    .from("release_manifests")
    .select("asset_digest, signature")
    .eq("build_id", buildId)
    .maybeSingle();
  if (!manifest || !manifest.signature || manifest.signature === "unsigned") {
    await safeViolation(
      "presign_unsigned_build",
      { purpose, buildId },
      licence.id,
      licence.license_key,
    );
    return deny("ATTESTATION_INVALID", "This build could not be verified.");
  }
  if (manifest.asset_digest !== assetDigest) {
    await safeViolation(
      "digest_mismatch",
      { purpose, buildId, reported: assetDigest, expected: manifest.asset_digest },
      licence.id,
      licence.license_key,
    );
    return deny("ATTESTATION_INVALID", "This build could not be verified.");
  }

  // Monthly bandwidth quota accounting & hard stop check
  if (projectId) {
    try {
      const { accountEgress } = await import("@/lib/project-usage.server");
      const usage = await accountEgress(projectId);
      if (!usage.allowed) {
        await safeViolation("quota_exceeded", { purpose, projectId, usage }, licence.id, licence.license_key);
        return deny("QUOTA_EXCEEDED", "Monthly bandwidth quota exceeded for this project.");
      }
    } catch {
      // Non-blocking fallback if usage tracking fails
    }
  }

  return { ok: true, enforced: true, deviceId: device.id, licenceKey: licence.license_key };
}

/** Violation logging must never be the reason a presign check crashes. */
async function safeViolation(
  kind: string,
  detail: Record<string, unknown>,
  licenseId?: string | null,
  licenceKey?: string,
) {
  try {
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    await supabaseAdmin.from("license_violations").insert({
      license_id: licenseId ?? null,
      kind,
      detail: { ...detail, ...(licenceKey ? { licenceKey } : {}) },
      ip_address: null,
      origin_host: null,
    });
  } catch {
    /* ignore */
  }
}

/**
 * Rate-limit adapter — one interface, four backends.
 *   upstash  (edge / main)        HTTP Redis, no TCP needed on Workers
 *   redis    (self-hosted)        node-redis against the Redis container
 *   postgres (either, fallback)   existing check_and_record_hit RPC
 *   memory   (dev / client-app)   per-isolate, best-effort only
 *
 * Everything above the adapter calls `check(key, limit, windowSeconds)`.
 */
import { rateLimitDriver, readEnv, requireEnv } from "./env.server";

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  /** True when the limiter store was unreachable and a fail mode was applied. */
  degraded?: boolean;
}

type Backend = (key: string, limit: number, windowSeconds: number) => Promise<RateLimitResult>;

let backend: Backend | null = null;

/** Fixed-window counter: INCR + EXPIRE on first hit. */
async function upstashBackend(): Promise<Backend> {
  const url = requireEnv("UPSTASH_REDIS_REST_URL").replace(/\/+$/, "");
  const token = requireEnv("UPSTASH_REDIS_REST_TOKEN");
  const call = async (cmd: unknown[]) => {
    const res = await fetch(url, {
      method: "POST",
      headers: { authorization: `Bearer ${token}`, "content-type": "application/json" },
      body: JSON.stringify(cmd),
    });
    if (!res.ok) throw new Error(`upstash [${res.status}]: ${await res.text()}`);
    return (await res.json()) as { result: number };
  };
  return async (key, limit, windowSeconds) => {
    const { result } = await call(["INCR", key]);
    if (result === 1) await call(["EXPIRE", key, windowSeconds]);
    return { allowed: result <= limit, remaining: Math.max(0, limit - result) };
  };
}

async function redisBackend(): Promise<Backend> {
  const url = requireEnv("REDIS_URL");
  const spec = "redis";
  const { createClient } = (await import(/* @vite-ignore */ spec)) as unknown as {
    createClient: (cfg: { url: string }) => {
      connect: () => Promise<unknown>;
      incr: (k: string) => Promise<number>;
      expire: (k: string, s: number) => Promise<unknown>;
    };
  };
  const client = createClient({ url });
  await client.connect();
  return async (key, limit, windowSeconds) => {
    const count = await client.incr(key);
    if (count === 1) await client.expire(key, windowSeconds);
    return { allowed: count <= limit, remaining: Math.max(0, limit - count) };
  };
}

async function postgresBackend(): Promise<Backend> {
  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  return async (key, limit, windowSeconds) => {
    const [bucket, ...rest] = key.split(":");
    const { data, error } = await supabaseAdmin.rpc("check_and_record_hit", {
      _bucket: bucket ?? "default",
      _key: rest.join(":") || key,
      _window_seconds: windowSeconds,
      _max: limit,
    });
    if (error) {
      console.error("[ratelimit:" + "postgres] " + error.message);
      return { allowed: true, remaining: limit }; // fail-open, same as before
    }
    return { allowed: data === true, remaining: data === true ? limit - 1 : 0 };
  };
}

function memoryBackend(): Backend {
  const hits = new Map<string, { count: number; resetAt: number }>();
  return async (key, limit, windowSeconds) => {
    const now = Date.now();
    const entry = hits.get(key);
    if (!entry || entry.resetAt < now) {
      hits.set(key, { count: 1, resetAt: now + windowSeconds * 1000 });
      return { allowed: true, remaining: limit - 1 };
    }
    entry.count += 1;
    return { allowed: entry.count <= limit, remaining: Math.max(0, limit - entry.count) };
  };
}

async function getBackend(): Promise<Backend> {
  if (backend) return backend;
  const driver = rateLimitDriver();
  if (driver === "upstash") backend = await upstashBackend();
  else if (driver === "redis") backend = await redisBackend();
  else if (driver === "postgres") backend = await postgresBackend();
  else {
    // `memory` is per-isolate and therefore NOT a real rate limit once more
    // than one worker is running. Hard rules:
    //   1. Admin builds (LICENCE_ROLE=issuer) must never use it — they issue
    //      tokens and write to the DB; an outage must never become unlimited.
    //   2. Edge runtime with multiple isolates makes the Map meaningless.
    //   3. client-app builds in production must use a real driver too.
    // The check covers all three without relying on NODE_ENV, which is not
    // reliably injected by the Cloudflare Workers deploy workflow.
    const role = readEnv("LICENCE_ROLE") ?? "client"; // default changed to "client"
    const rt = readEnv("RUNTIME") ?? "edge";
    const isAdminBuild = role === "issuer";
    const isEdge = rt === "edge";
    const isProduction = (readEnv("NODE_ENV") ?? "development") === "production";

    if (isAdminBuild || isEdge || isProduction) {
      throw new Error(
        "RATELIMIT_DRIVER=memory is a development-only driver and cannot start on " +
          `this deployment (LICENCE_ROLE=${role}, RUNTIME=${rt}, NODE_ENV=${readEnv("NODE_ENV") ?? "development"}). ` +
          "Set RATELIMIT_DRIVER to upstash, redis, or postgres.",
      );
    }
    backend = memoryBackend();
  }
  return backend;
}


/**
 * Returns allowed=false when the caller has exceeded `limit` in the window.
 *
 * `failMode` decides what happens when the limiter store itself is unreachable:
 *   "closed" (default) — deny. Correct for every mutation (activate, release,
 *                        admin writes, PIN attempts): an outage must not become
 *                        an unlimited brute-force window.
 *   "open"             — allow. Only for read-only heartbeat/refresh, where a
 *                        KV outage would otherwise brick every client AR viewer
 *                        simultaneously. Always logged.
 */
export async function check(
  key: string,
  limit: number,
  windowSeconds: number,
  opts: { failMode?: "closed" | "open" } = {},
): Promise<RateLimitResult> {
  const failMode = opts.failMode ?? "closed";
  try {
    const run = await getBackend();
    return await run(key, limit, windowSeconds);
  } catch (e) {
    console.error(`[ratelimit] backend error, failing ${failMode} for ${key}:`, e);
    if (failMode === "open") return { allowed: true, remaining: limit, degraded: true };
    return { allowed: false, remaining: 0, degraded: true };
  }
}

export function __setBackend(fn: Backend | null) {
  backend = fn;
}

export const currentDriver = rateLimitDriver;
export const isConfigured = () =>
  Boolean(readEnv("UPSTASH_REDIS_REST_URL") || readEnv("REDIS_URL"));

import type { SupabaseClient } from "@supabase/supabase-js";

/**
 * Server-side admin gate for server functions.
 *
 * The check runs with the CALLER's own Supabase client (RLS applies), so a
 * user can only ever see their own `user_roles` row — a forged request body
 * or a tampered client bundle cannot promote anybody. Never use the service
 * role client to establish that the caller is an admin.
 *
 * Throws a plain 403 Response so unauthorised callers get a safe, generic
 * error with no schema or role details leaked.
 */
export async function requireAdmin(context: {
  supabase: SupabaseClient<any, any, any>;
  userId: string;
}): Promise<void> {
  const { data, error } = await context.supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", context.userId)
    .eq("role", "admin")
    .maybeSingle();

  if (error || !data) {
    throw new Response("Forbidden", { status: 403 });
  }
}

/** Non-throwing variant, for UI that only needs to branch on the role. */
export async function isAdmin(context: {
  supabase: SupabaseClient<any, any, any>;
  userId: string;
}): Promise<boolean> {
  const { data } = await context.supabase
    .from("user_roles")
    .select("role")
    .eq("user_id", context.userId)
    .eq("role", "admin")
    .maybeSingle();
  return !!data;
}

