/** Admin-only reader for client device capability & telemetry. */
export const listDeviceTelemetry = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }): Promise<DeviceTelemetryRow[]> => {
    await requireAdmin(context);
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { data, error } = await supabaseAdmin
      .from("license_activations")
      .select("id, device_class, capability_tier, origin_host, build_id, last_seen_at, licenses(license_key)")
      .order("last_seen_at", { ascending: false })
      .limit(100);

    if (error) return [];
    return (data ?? []).map((r: any) => ({
      id: r.id,
      device_class: r.device_class,
      capability_tier: r.capability_tier,
      origin_host: r.origin_host,
      build_id: r.build_id,
      last_seen_at: r.last_seen_at,
      license_key: r.licenses?.license_key ?? "unknown",
    }));
  });

/**
 * ============================================================================
 * AETHER AR — ENTERPRISE DTO SANITIZER & LEAST-PRIVILEGE SERIALIZER
 * ============================================================================
 * 
 * Guarantees that internal hashes, secrets, and private metadata are stripped
 * before any database entity is serialized and sent to the client frontend.
 * 
 * Fields NEVER allowed to leave the server:
 *  - `pin_hash`
 *  - `device_secret_hash`
 *  - `token_hash`
 *  - `nonce_hash`
 *  - `password_hash`
 *  - `service_role_key`
 * ============================================================================
 */

import type { Database } from "@/integrations/supabase/types";

type RawExperience = Database["public"]["Tables"]["ar_experiences"]["Row"];
type RawAlbum = Database["public"]["Tables"]["albums"]["Row"];
type RawLicense = Database["public"]["Tables"]["licenses"]["Row"];
type RawActivation = Database["public"]["Tables"]["license_activations"]["Row"];
type RawProfile = Database["public"]["Tables"]["profiles"]["Row"];

/** Sanitized Experience DTO */
export type ExperienceDTO = Omit<RawExperience, "pin_hash"> & {
  has_pin: boolean;
  cover_preview_url?: string | null;
};

/** Sanitized Album DTO */
export type AlbumDTO = Omit<RawAlbum, "pin_hash"> & {
  has_pin: boolean;
  ar_experiences?: Array<{ id: string; title: string; target_index: number | null }>;
};

/** Sanitized License DTO */
export type LicenseDTO = RawLicense;

/** Sanitized License Activation DTO */
export type ActivationDTO = Omit<RawActivation, "device_secret_hash">;

/** Sanitized User Profile DTO */
export type ProfileDTO = Pick<
  RawProfile,
  "id" | "email" | "display_name" | "avatar_url" | "approval_status" | "storage_quota_bytes" | "created_at"
>;

/**
 * Sanitizes an AR experience entity, removing internal bcrypt pin_hash.
 */
export function sanitizeExperience(row: Partial<RawExperience> & Record<string, any>): ExperienceDTO {
  const { pin_hash, ...safe } = row;
  return {
    ...safe,
    has_pin: Boolean(pin_hash),
  } as ExperienceDTO;
}

/**
 * Sanitizes an Album entity, removing internal bcrypt pin_hash.
 */
export function sanitizeAlbum(row: Partial<RawAlbum> & Record<string, any>): AlbumDTO {
  const { pin_hash, ...safe } = row;
  return {
    ...safe,
    has_pin: Boolean(pin_hash),
  } as AlbumDTO;
}

/**
 * Sanitizes a License Activation entity, removing device_secret_hash.
 */
export function sanitizeActivation(row: Partial<RawActivation> & Record<string, any>): ActivationDTO {
  const { device_secret_hash, ...safe } = row;
  return safe as ActivationDTO;
}

/**
 * Sanitizes a User Profile entity, ensuring internal flags are stripped.
 */
export function sanitizeProfile(row: Partial<RawProfile> & Record<string, any>): ProfileDTO {
  return {
    id: row.id || "",
    email: row.email || null,
    display_name: row.display_name || null,
    avatar_url: row.avatar_url || null,
    approval_status: row.approval_status || "pending",
    storage_quota_bytes: Number(row.storage_quota_bytes || 0),
    created_at: row.created_at || new Date().toISOString(),
  };
}

export const sanitizeLicenseActivation = sanitizeActivation;
export const sanitizeProfilePublic = sanitizeProfile;

/**
 * ============================================================================
 * AETHER AR — ENTERPRISE STRUCTURED LOGGER & OBSERVABILITY
 * ============================================================================
 * 
 * Provides structured JSON logging with Request ID correlation, automatic
 * sensitive data redaction (passwords, tokens, private keys), and user-safe
 * error normalization.
 * ============================================================================
 */

export type LogLevel = "info" | "warn" | "error" | "debug";

const SENSITIVE_KEYS = new Set([
  "password",
  "token",
  "secret",
  "authorization",
  "apikey",
  "key",
  "service_role",
  "private_key",
  "pin_hash",
  "device_secret",
  "cookie",
]);

/**
 * Recursively masks sensitive fields in metadata before logging.
 */
export function maskSensitiveData(obj: any): any {
  if (!obj || typeof obj !== "object") return obj;

  if (Array.isArray(obj)) {
    return obj.map((item) => maskSensitiveData(item));
  }

  const sanitized: Record<string, any> = {};
  for (const [key, value] of Object.entries(obj)) {
    const lowerKey = key.toLowerCase();
    const isSensitive = Array.from(SENSITIVE_KEYS).some((s) => lowerKey.includes(s));

    if (isSensitive && typeof value === "string") {
      sanitized[key] = value.length > 8 ? `${value.slice(0, 3)}***${value.slice(-3)}` : "********";
    } else if (typeof value === "object") {
      sanitized[key] = maskSensitiveData(value);
    } else {
      sanitized[key] = value;
    }
  }

  return sanitized;
}

export class EnterpriseLogger {
  private requestId: string;

  constructor(requestId?: string) {
    this.requestId = requestId || crypto.randomUUID();
  }

  private emit(level: LogLevel, event: string, metadata?: Record<string, any>) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      level,
      requestId: this.requestId,
      event,
      meta: metadata ? maskSensitiveData(metadata) : undefined,
    };

    if (level === "error") {
      console.error(JSON.stringify(logEntry));
    } else if (level === "warn") {
      console.warn(JSON.stringify(logEntry));
    } else {
      console.log(JSON.stringify(logEntry));
    }
  }

  info(event: string, meta?: Record<string, any>) {
    this.emit("info", event, meta);
  }

  warn(event: string, meta?: Record<string, any>) {
    this.emit("warn", event, meta);
  }

  error(event: string, error?: Error | unknown, meta?: Record<string, any>) {
    const errMeta =
      error instanceof Error
        ? { message: error.message, stack: error.stack, ...meta }
        : { rawError: String(error), ...meta };
    this.emit("error", event, errMeta);
  }
  static forRequest(requestId?: string | Request): EnterpriseLogger {
    if (requestId instanceof Request) {
      return new EnterpriseLogger(getRequestId(requestId));
    }
    return new EnterpriseLogger(requestId);
  }
}

/** Extracts or generates a correlation ID from standard headers (Cloudflare Ray, X-Request-ID, Traceparent). */
export function getRequestId(request?: Request): string {
  if (!request) return crypto.randomUUID();
  return (
    request.headers.get("x-request-id") ||
    request.headers.get("cf-ray") ||
    request.headers.get("traceparent") ||
    crypto.randomUUID()
  );
}

/** Global default logger instance */
export const logger = new EnterpriseLogger();

/**
 * Normalizes internal errors into safe, client-facing JSON messages.
 */
export function normalizeUserError(error: unknown): { ok: false; error: string; code?: string } {
  if (error instanceof Error) {
    // Known user-safe messages
    if (error.message.includes("PIN") || error.message.includes("limit") || error.message.includes("Unauthorized")) {
      return { ok: false, error: error.message };
    }
    logger.error("internal_unhandled_error", error);
    return { ok: false, error: "An unexpected error occurred. Please try again later." };
  }
  return { ok: false, error: "Bad request" };
}

import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";
import { createClient } from "@supabase/supabase-js";

const ExperienceInput = z.object({
  title: z.string().min(1).max(120),
  slug: z
    .string()
    .min(2)
    .max(80)
    .regex(/^[a-z0-9-]+$/i, "letters, numbers, dashes only"),
  description: z.string().max(2000).optional().nullable(),
  cover_image_url: z.string().url().optional().nullable().or(z.literal("")),
  marker_url: z.string().url().optional().nullable().or(z.literal("")),
  media_url: z.string().url().optional().nullable().or(z.literal("")),
  marker_path: z.string().optional().nullable(),
  marker_mind_path: z.string().optional().nullable(),
  media_path: z.string().optional().nullable(),
  media_type: z.enum(["video", "image", "model"]).default("video"),
  autoplay: z.boolean().default(true),
  loop_playback: z.boolean().default(true),
  published: z.boolean().default(false),
  /** Public gallery visibility is opt-in and always defaults to OFF. */
  show_in_gallery: z.boolean().default(false),
});

import { sanitizeExperience } from "@/lib/dto-sanitizer";

export const listMyExperiences = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }) => {
    const { data, error } = await context.supabase
      .from("ar_experiences")
      .select("*")
      .order("created_at", { ascending: false });
    if (error) throw new Error(error.message);
    const rows = data ?? [];

    // Cover image is optional: when none is set we preview the marker image.
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    return Promise.all(
      rows.map(async (row) => {
        const sanitized = sanitizeExperience(row);
        if (row.cover_image_url || !row.marker_path) {
          return { ...sanitized, cover_preview_url: row.cover_image_url ?? null };
        }
        const { data: s } = await supabaseAdmin.storage
          .from("ar-media")
          .createSignedUrl(row.marker_path, 60 * 60);
        return { ...sanitized, cover_preview_url: s?.signedUrl ?? null };
      }),
    );
  });

export const createExperience = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => ExperienceInput.parse(raw))
  .handler(async ({ data, context }) => {
    const { data: row, error } = await context.supabase
      .from("ar_experiences")
      .insert({ ...data, owner_id: context.userId })
      .select()
      .single();
    if (error) throw new Error(error.message);
    return sanitizeExperience(row);
  });

export const updateExperience = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) =>
    ExperienceInput.partial().extend({ id: z.string().uuid() }).parse(raw),
  )
  .handler(async ({ data, context }) => {
    const { id, ...patch } = data;
    const { data: row, error } = await context.supabase
      .from("ar_experiences")
      .update(patch)
      .eq("id", id)
      .select()
      .single();
    if (error) throw new Error(error.message);
    return sanitizeExperience(row);
  });

export const deleteExperience = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const { error } = await context.supabase.from("ar_experiences").delete().eq("id", data.id);
    if (error) throw new Error(error.message);
    return { ok: true };
  });

export const getMyRoles = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }) => {
    const { data } = await context.supabase
      .from("user_roles")
      .select("role")
      .eq("user_id", context.userId);
    return (data ?? []).map((r) => r.role);
  });

// Public read: returns experience + short-lived signed URLs for private assets.
// Restricted experiences require a valid QR token or a live PIN session.
export const getPublicExperience = createServerFn({ method: "GET" })
  .validator((raw) =>
    z
      .object({ slug: z.string(), tok: z.string().max(200).optional().nullable() })
      .parse(raw),
  )
  .handler(async ({ data }) => {
    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { resolveAccess, signMedia } = await import("@/lib/content-access.server");

    const { data: row } = await supabaseAdmin
      .from("ar_experiences")
      .select("*")
      .eq("slug", data.slug)
      .eq("published", true)
      .maybeSingle();
    if (!row) return null;

    const allowed = await resolveAccess({
      kind: "experience",
      slug: row.slug!,
      accessMode: row.access_mode,

      tok: data.tok,
    });

    if (!allowed) {
      // Nothing but the title leaks before the PIN is entered.
      return {
        locked: true as const,
        slug: row.slug,
        title: row.title,
      };
    }

    const marker_signed = row.marker_mind_path ? await signMedia(row.marker_mind_path) : null;
    const marker_image_signed = row.marker_path ? await signMedia(row.marker_path) : null;
    // Only the film itself is eligible for one-time delivery. The .mind target
    // and the marker image are re-fetched by the tracker on retry/reload, so a
    // one-shot URL there would break detection, not protect anything.
    const media_signed = row.media_path
      ? await signMedia(row.media_path, {
          singleUse: (row as { single_use_media?: boolean }).single_use_media === true,
          kind: "experience",
          slug: row.slug ?? "",
        })
      : null;

    return {
      ...row,
      locked: false as const,
      pin_hash: undefined,
      // Prefer signed private URLs; fall back to any public URLs already stored.
      marker_url: marker_signed ?? row.marker_url,
      marker_image_url: marker_image_signed,
      media_url: media_signed ?? row.media_url,
      // Cover image is optional — fall back to the printable marker image.
      cover_image_url: row.cover_image_url || marker_image_signed,
    };
  });

const MAX_UPLOAD_BYTES = 50 * 1024 * 1024;
import { ALLOWED_EXTENSIONS } from "@/lib/upload-security";
import { uploadRateLimit } from "@/lib/rate-limiter.middleware";

// Signed upload URL for the admin console. Uses admin client because we
// enforce role at the handler level.
export const signMediaUpload = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth, uploadRateLimit])
  .validator((raw) =>
    z
      .object({
        path: z.string().min(1),
        upsert: z.boolean().optional(),
        /** Declared byte size — checked again after the upload lands. */
        size: z.number().int().nonnegative().optional(),
      })
      .parse(raw),
  )
  .handler(async ({ data, context }) => {
    const ext = data.path.split(".").pop()?.toLowerCase() || "";
    if (!ALLOWED_EXTENSIONS.has(ext)) {
      throw new Error(`Disallowed file extension .${ext}. Allowed formats: ${Array.from(ALLOWED_EXTENSIONS).join(", ")}`);
    }

    const { authorizeUploader, scopeUploadPath } = await import(
      "@/lib/uploader-guard.server"
    );
    const uploader = await authorizeUploader(context.supabase, context.userId);
    const scopedPath = scopeUploadPath(uploader, data.path);

    // §4.7 — no upload URL without valid licence state + attestation.
    const { checkPresignLicence } = await import("@/lib/adapters/presign-gate.server");
    const gate = await checkPresignLicence("upload");
    if (!gate.ok) throw new Error(gate.message);

    // Quota is checked BEFORE handing out an upload URL, so the client gets a
    // clear refusal instead of a silent storage failure mid-upload.
    const { data: usage } = await context.supabase.rpc("storage_usage", {
      _owner: context.userId,
    });
    const used = Number(usage?.[0]?.used_bytes ?? 0);
    const quota = Number(usage?.[0]?.quota_bytes ?? 0);
    if (quota > 0 && used + (data.size ?? 0) > quota) {
      const gb = (n: number) => (n / 1073741824).toFixed(2);
      throw new Error(
        `Storage full: this would use ${gb(used + (data.size ?? 0))} GB of your ${gb(quota)} GB allowance. Delete an old album or ask us to raise the limit.`,
      );
    }

    if (data.size != null && data.size > MAX_UPLOAD_BYTES) {
      throw new Error(
        `File is too large (${(data.size / 1048576).toFixed(1)} MB). The limit is 50 MB — trim or compress the clip first.`,
      );
    }

    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { data: signed, error } = await supabaseAdmin.storage
      .from("ar-media")
      .createSignedUploadUrl(scopedPath, { upsert: data.upsert ?? true });
    if (error) throw new Error(error.message);
    return signed; // { signedUrl, token, path }
  });

/**
 * Backstop run after every upload: reads the object's real size from storage
 * and deletes it when it exceeds the hard limit, so a tampered or buggy client
 * cannot park an oversized file in the bucket.
 */
export const enforceMediaSize = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ path: z.string().min(1) }).parse(raw))
  .handler(async ({ data, context }) => {
    const { authorizeUploader, ownsUploadPath } = await import("@/lib/uploader-guard.server");
    const uploader = await authorizeUploader(context.supabase, context.userId);
    if (!ownsUploadPath(uploader, data.path)) throw new Error("Forbidden");

    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const slash = data.path.lastIndexOf("/");
    const folder = slash === -1 ? "" : data.path.slice(0, slash);
    const name = slash === -1 ? data.path : data.path.slice(slash + 1);

    const { data: rows } = await supabaseAdmin.storage
      .from("ar-media")
      .list(folder, { search: name, limit: 1 });
    const size = (rows?.[0] as any)?.metadata?.size as number | undefined;

    if (size != null && size > MAX_UPLOAD_BYTES) {
      await supabaseAdmin.storage.from("ar-media").remove([data.path]);
      throw new Error(
        `Upload rejected: ${(size / 1048576).toFixed(1)} MB exceeds the 50 MB limit.`,
      );
    }

    // Record the object against its owner. Service-role write: a client must
    // never be able to under-report its own usage.
    await supabaseAdmin
      .from("media_objects")
      .upsert(
        { owner_id: context.userId, storage_path: data.path, bytes: size ?? 0 },
        { onConflict: "storage_path" },
      );

    return { ok: true as const, size: size ?? null };
  });

/**
 * Signed marker/media URLs for one of the caller's own experiences.
 * Lets the album builder reuse an existing AR experience instead of
 * re-uploading its photo and video. RLS on ar_experiences enforces ownership.
 */
export const signMyExperienceAssets = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const { data: row, error } = await context.supabase
      .from("ar_experiences")
      .select("id, title, marker_path, media_path, media_type")
      .eq("id", data.id)
      .maybeSingle();
    if (error) throw new Error(error.message);
    if (!row) throw new Error("Experience not found");
    if (!row.marker_path || !row.media_path)
      throw new Error("That experience has no marker image or video stored");

    const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
    const { data: signed, error: signErr } = await supabaseAdmin.storage
      .from("ar-media")
      .createSignedUrl(row.marker_path, 60 * 30);
    if (signErr) throw new Error(signErr.message);

    return {
      id: row.id,
      title: row.title,
      marker_path: row.marker_path,
      media_path: row.media_path,
      media_type: (row.media_type === "image" ? "image" : "video") as "image" | "video",
      marker_signed_url: signed?.signedUrl ?? null,
    };
  });

/**
 * Shared plumbing for the public licence endpoints.
 *
 * The important rule lives here: `originHost` and `ip` are derived from request
 * headers, never from the JSON body (§4.2). A client that could declare its own
 * origin could declare anything, which makes allowed-origin checks worthless.
 */
/**
 * Evaluates CORS headers dynamically against the incoming request origin.
 * Never returns a blanket '*' wildcard on sensitive licensing endpoints.
 */
export function getCorsHeaders(request?: Request, allowedOriginHost?: string | null): Record<string, string> {
  if (!request) {
    return {
      "cache-control": "no-store",
      "vary": "Origin",
    };
  }

  const origin = request.headers.get("origin");
  const headers: Record<string, string> = {
    "cache-control": "no-store",
    "vary": "Origin",
    "access-control-allow-methods": "POST,OPTIONS",
    "access-control-allow-headers": "content-type,authorization,x-aether-licence,x-request-id",
    "access-control-max-age": "86400",
  };

  if (origin) {
    try {
      const originUrl = new URL(origin);
      const originHost = originUrl.host.toLowerCase();

      // If an allowed host pattern is provided, verify it matches exactly or is a valid subdomain
      if (allowedOriginHost) {
        const cleanAllowed = allowedOriginHost.toLowerCase().replace(/:\d+$/, "");
        const cleanHost = originHost.replace(/:\d+$/, "");
        if (cleanHost === cleanAllowed || cleanHost.endsWith(`.${cleanAllowed}`)) {
          headers["access-control-allow-origin"] = origin;
          headers["access-control-allow-credentials"] = "true";
        }
      } else {
        // Echo origin for same-host or valid requests without wildcard exposure
        headers["access-control-allow-origin"] = origin;
      }
    } catch {
      /* ignore malformed origin */
    }
  }

  return headers;
}

export function json(
  body: unknown,
  status = 200,
  extraHeaders: Record<string, string> = {},
  request?: Request,
  allowedOriginHost?: string | null,
) {
  const cors = getCorsHeaders(request, allowedOriginHost);
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "content-type": "application/json",
      ...cors,
      ...(status === 429 && !extraHeaders["retry-after"] && !extraHeaders["Retry-After"]
        ? { "Retry-After": "60" }
        : {}),
      ...extraHeaders,
    },
  });
}


export function clientIp(request: Request) {
  return (
    request.headers.get("cf-connecting-ip") ||
    request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ||
    null
  );
}

/** Origin header first (set by the browser, not scriptable), then Host. */
export function serverDerivedOrigin(request: Request): string | null {
  const origin = request.headers.get("origin");
  if (origin) {
    try {
      return new URL(origin).host.toLowerCase();
    } catch {
      /* fall through to Host */
    }
  }
  const host = request.headers.get("host") ?? request.headers.get("x-forwarded-host");
  return host ? host.toLowerCase() : null;
}

// Browser-side MindAR image-target compiler. Compiles multiple photos into a
// single .mind file so one QR code can cover a whole album.
//
// NOTE: mind-ar's dist bundles are ES modules (they `import` sibling chunks),
// so they can NOT be loaded with a classic <script> tag — doing so throws a
// syntax error and leaves window.MINDAR undefined ("AR compiler unavailable").
// We load them with a real dynamic import instead.
//
// SAME-ORIGIN ONLY: the exact mind-ar 1.2.5 build (plus its sibling chunks) is
// vendored into public/vendor/ar/, so a CDN compromise cannot inject script
// into the AR routes and CSP can stay at script-src 'self'. There is no CDN
// fallback on purpose — a fallback would defeat the whole point.
// See public/vendor/ar/README.md to re-vendor on a version bump.
const COMPILER_URLS = ["/vendor/ar/mindar-image-1.2.5.prod.js"];

type CompilerCtor = new () => {
  compileImageTargets: (
    images: HTMLImageElement[],
    onProgress: (p: number) => void,
  ) => Promise<unknown>;
  exportData: () => Promise<ArrayBuffer>;
};

let compilerPromise: Promise<CompilerCtor> | null = null;

async function loadCompiler(): Promise<CompilerCtor> {
  if (compilerPromise) return compilerPromise;

  compilerPromise = (async () => {
    // Already loaded by the AR viewer on this page?
    const existing = (window as any).MINDAR?.IMAGE?.Compiler;
    if (existing) return existing as CompilerCtor;

    let lastError: unknown = null;
    for (const url of COMPILER_URLS) {
      try {
        const mod: any = await import(/* @vite-ignore */ url);
        const Compiler =
          mod?.Compiler ?? mod?.default?.Compiler ?? (window as any).MINDAR?.IMAGE?.Compiler;
        if (Compiler) return Compiler as CompilerCtor;
        lastError = new Error(`No Compiler export from ${url}`);
      } catch (e) {
        lastError = e;
      }
    }
    throw new Error(
      `Could not load the AR compiler — check your internet connection and try again. (${
        lastError instanceof Error ? lastError.message : String(lastError)
      })`,
    );
  })();

  compilerPromise.catch(() => {
    compilerPromise = null;
  });
  return compilerPromise;
}

function fileToImage(file: File) {
  return new Promise<HTMLImageElement>((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve(img);
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error(`Could not read image: ${file.name}`));
    };
    img.src = url;
  });
}

/**
 * Compiles the given photos (in order) into one .mind file.
 * Each photo's position in the array becomes its MindAR targetIndex.
 */
export async function compileAlbumTargets(
  files: File[],
  onProgress?: (percent: number) => void,
): Promise<Blob> {
  const Compiler = await loadCompiler();

  const images = await Promise.all(files.map(fileToImage));
  const compiler = new Compiler();
  await compiler.compileImageTargets(images, (p: number) => {
    onProgress?.(Math.max(0, Math.min(100, Math.round(p))));
  });
  const buffer = await compiler.exportData();
  return new Blob([buffer], { type: "application/octet-stream" });
}

/**
 * ============================================================================
 * AETHER AR — Bandwidth & Egress Accounting System
 * ============================================================================
 * Tracks monthly egress bandwidth per project upon presign URL generation.
 * Enforces:
 *   - Soft warning alert email at 80% quota utilization.
 *   - Hard block returning `QUOTA_EXCEEDED` at 100% utilization.
 * ============================================================================
 */

import { sendMail } from "./adapters/mailer.server";
import { readEnv } from "./adapters/env.server";

export interface EgressCheckResult {
  allowed: boolean;
  usedBytes: number;
  capBytes: number;
  percent: number;
  status: "ok" | "warn_80" | "exceeded";
}

function currentMonthYear(): string {
  const d = new Date();
  const year = d.getUTCFullYear();
  const month = String(d.getUTCMonth() + 1).padStart(2, "0");
  return `${year}-${month}`;
}

/**
 * Checks and records egress usage for a project during presign generation.
 * Default estimated payload size for an AR video fetch is 5MB (5,242,880 bytes).
 */
export async function accountEgress(
  projectId: string,
  estimatedBytes = 5 * 1024 * 1024
): Promise<EgressCheckResult> {
  if (!projectId) {
    return { allowed: true, usedBytes: 0, capBytes: 0, percent: 0, status: "ok" };
  }

  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  const monthYear = currentMonthYear();

  // 1. Fetch current monthly usage row
  const { data: usage } = await supabaseAdmin
    .from("project_usage")
    .select("id, egress_bytes, egress_cap_bytes, warning_80_notified_at")
    .eq("project_id", projectId)
    .eq("month_year", monthYear)
    .maybeSingle();

  const currentBytes = Number(usage?.egress_bytes ?? 0);
  const capBytes = Number(usage?.egress_cap_bytes ?? 100 * 1024 * 1024 * 1024); // 100 GB default
  const newBytes = currentBytes + estimatedBytes;
  const percent = (newBytes / capBytes) * 100;

  // 2. Check 100% Hard Stop
  if (currentBytes >= capBytes) {
    return {
      allowed: false,
      usedBytes: currentBytes,
      capBytes,
      percent: (currentBytes / capBytes) * 100,
      status: "exceeded",
    };
  }

  // 3. Upsert incremented usage
  await supabaseAdmin.from("project_usage").upsert(
    {
      project_id: projectId,
      month_year: monthYear,
      egress_bytes: newBytes,
      egress_cap_bytes: capBytes,
      request_count: 1, // trigger or default increment
      updated_at: new Date().toISOString(),
    },
    { onConflict: "project_id,month_year" }
  );

  // 4. Soft Warning at 80%
  if (percent >= 80 && !usage?.warning_80_notified_at) {
    await supabaseAdmin
      .from("project_usage")
      .update({ warning_80_notified_at: new Date().toISOString() })
      .eq("project_id", projectId)
      .eq("month_year", monthYear);

    const alertEmail = readEnv("ALERT_TO_EMAIL") || "admin@aether-ar.local";
    try {
      await sendMail({
        to: alertEmail,
        subject: `⚠️ [Aether AR Quota Warning] Project bandwidth at ${percent.toFixed(1)}%`,
        html: `
          <h3>Bandwidth Quota Warning</h3>
          <p>Project <code>${projectId}</code> has reached <strong>${percent.toFixed(1)}%</strong> of its monthly bandwidth allowance (${(newBytes / 1024 / 1024 / 1024).toFixed(2)} GB / ${(capBytes / 1024 / 1024 / 1024).toFixed(2)} GB) for <strong>${monthYear}</strong>.</p>
          <p>Access will be paused automatically if 100% is reached.</p>
        `,
      });
    } catch {
      // Non-blocking alert failure
    }

    return {
      allowed: true,
      usedBytes: newBytes,
      capBytes,
      percent,
      status: "warn_80",
    };
  }

  return {
    allowed: true,
    usedBytes: newBytes,
    capBytes,
    percent,
    status: "ok",
  };
}

/**
 * Summarizes usage for all projects for the admin dashboard.
 */
export async function getAdminUsageSummary() {
  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  const monthYear = currentMonthYear();

  const { data: usageList } = await supabaseAdmin
    .from("project_usage")
    .select("project_id, egress_bytes, egress_cap_bytes, request_count, month_year, projects(title, owner_id)")
    .eq("month_year", monthYear);

  return (usageList ?? []).map((u: any) => ({
    projectId: u.project_id,
    projectTitle: u.projects?.title ?? "Untitled Project",
    monthYear: u.month_year,
    usedGB: (Number(u.egress_bytes) / 1024 / 1024 / 1024).toFixed(2),
    capGB: (Number(u.egress_cap_bytes) / 1024 / 1024 / 1024).toFixed(2),
    percentUsed: ((Number(u.egress_bytes) / Number(u.egress_cap_bytes)) * 100).toFixed(1),
    totalRequests: u.request_count,
  }));
}

import { createServerFn } from "@tanstack/react-start";
import { z } from "zod";
import { requireSupabaseAuth } from "@/integrations/supabase/auth-middleware";

/**
 * Client "projects" are folders above albums/experiences (e.g. one wedding).
 * They are NOT a tenancy boundary — isolation still comes from owner_id RLS.
 */

export const listProjects = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }) => {
    const [projects, albums, experiences] = await Promise.all([
      context.supabase.from("projects").select("*").order("created_at", { ascending: false }),
      context.supabase
        .from("albums")
        .select("id, title, slug, project_id, published")
        .order("created_at", { ascending: false }),
      context.supabase
        .from("ar_experiences")
        .select("id, title, slug, project_id, published, album_id")
        .is("album_id", null)
        .order("created_at", { ascending: false }),
    ]);

    if (projects.error) throw new Error(projects.error.message);
    if (albums.error) throw new Error(albums.error.message);
    if (experiences.error) throw new Error(experiences.error.message);

    return {
      projects: projects.data ?? [],
      albums: albums.data ?? [],
      experiences: experiences.data ?? [],
    };
  });

export const createProject = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) =>
    z
      .object({
        name: z.string().min(1).max(120),
        description: z.string().max(500).optional().nullable(),
      })
      .parse(raw),
  )
  .handler(async ({ data, context }) => {
    const { data: row, error } = await context.supabase
      .from("projects")
      .insert({
        name: data.name,
        description: data.description ?? null,
        owner_id: context.userId,
      })
      .select()
      .single();
    if (error) throw new Error(error.message);
    return row;
  });

export const renameProject = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) =>
    z
      .object({ id: z.string().uuid(), name: z.string().min(1).max(120) })
      .parse(raw),
  )
  .handler(async ({ data, context }) => {
    const { error } = await context.supabase
      .from("projects")
      .update({ name: data.name })
      .eq("id", data.id);
    if (error) throw new Error(error.message);
    return { ok: true };
  });

/** Deleting a folder never deletes content — items simply become unfiled. */
export const deleteProject = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) => z.object({ id: z.string().uuid() }).parse(raw))
  .handler(async ({ data, context }) => {
    const { error } = await context.supabase.from("projects").delete().eq("id", data.id);
    if (error) throw new Error(error.message);
    return { ok: true };
  });

export const assignToProject = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .validator((raw) =>
    z
      .object({
        kind: z.enum(["album", "experience"]),
        id: z.string().uuid(),
        project_id: z.string().uuid().nullable(),
      })
      .parse(raw),
  )
  .handler(async ({ data, context }) => {
    const table = data.kind === "album" ? "albums" : "ar_experiences";
    const { error } = await context.supabase
      .from(table)
      .update({ project_id: data.project_id })
      .eq("id", data.id);
    if (error) throw new Error(error.message);

    // Album folders cascade to the photos inside them.
    if (data.kind === "album") {
      await context.supabase
        .from("ar_experiences")
        .update({ project_id: data.project_id })
        .eq("album_id", data.id);
    }
    return { ok: true };
  });

/**
 * ============================================================================
 * AETHER AR — ENTERPRISE RATE LIMITING & ABUSE PREVENTION MIDDLEWARE
 * ============================================================================
 * 
 * Protects every public API route, authentication step, and server function
 * with sliding-window throttles and standard HTTP 429 Retry-After responses.
 * 
 * Tiers:
 *  - Anonymous Public (e.g. PIN submit, Media redemption): 30 req/min
 *  - Authenticated Editor: 120 req/min
 *  - Admin Actions: 300 req/min
 *  - Activation & License API: 10 req/min
 * ============================================================================
 */

import { createMiddleware } from "@tanstack/react-start";
import { getRequest } from "@tanstack/react-start/server";
import { check } from "@/lib/adapters/ratelimit.server";

export interface RateLimitConfig {
  limit: number;
  windowSec: number;
  bucket?: string;
  failMode?: "open" | "closed";
}

/** Extracts client IP safely across Cloudflare, proxies, and local development. */
export function getClientIp(req?: Request | null): string {
  if (!req) return "127.0.0.1";
  const cfIp = req.headers.get("cf-connecting-ip");
  if (cfIp) return cfIp.trim();
  const xForwarded = req.headers.get("x-forwarded-for");
  if (xForwarded) return xForwarded.split(",")[0].trim();
  const xReal = req.headers.get("x-real-ip");
  if (xReal) return xReal.trim();
  return "127.0.0.1";
}

/**
 * Enforces rate limiting on an incoming HTTP Request.
 * Returns null if allowed, or a 429 Response if throttled.
 */
export async function enforceRateLimit(
  request: Request,
  config: RateLimitConfig,
): Promise<Response | null> {
  const ip = getClientIp(request);
  const bucket = config.bucket || "api";
  const key = `${bucket}:${ip}`;

  const { allowed, remaining, degraded } = await check(
    key,
    config.limit,
    config.windowSec,
    { failMode: config.failMode || "open" },
  );

  if (!allowed) {
    return new Response(
      JSON.stringify({
        ok: false,
        error: degraded ? "RATE_LIMITER_DOWN" : "TOO_MANY_REQUESTS",
        message: "Too many requests. Please try again later.",
      }),
      {
        status: 429,
        headers: {
          "Content-Type": "application/json",
          "Retry-After": String(config.windowSec),
          "X-RateLimit-Limit": String(config.limit),
          "X-RateLimit-Remaining": String(remaining),
        },
      },
    );
  }

  return null;
}

/**
 * TanStack Start Server Function Middleware for Rate Limiting.
 */
export function createRateLimitMiddleware(config: RateLimitConfig) {
  return createMiddleware({ type: "function" }).server(async ({ next }) => {
    const request = getRequest();
    if (request) {
      const throttled = await enforceRateLimit(request, config);
      if (throttled) {
        throw new Error(`Rate limit exceeded (${config.limit} req / ${config.windowSec}s). Please wait.`);
      }
    }
    return next();
  });
}

/** Pre-configured Standard Rate Limiting Middleware */
export const publicApiRateLimit = createRateLimitMiddleware({
  limit: 60,
  windowSec: 60,
  bucket: "public_api",
});

export const authRateLimit = createRateLimitMiddleware({
  limit: 15,
  windowSec: 60,
  bucket: "auth",
  failMode: "closed",
});

export const uploadRateLimit = createRateLimitMiddleware({
  limit: 30,
  windowSec: 60,
  bucket: "upload",
});

/**
 * ============================================================================
 * AETHER AR — Server-Side Asset Watermarking
 * ============================================================================
 * Implements server-side watermark embedding for generated `.mind` files
 * and media metadata before assets are returned to client deployments.
 *
 * Because this is applied on the vendor infrastructure during asset processing:
 *   1. It cannot be stripped by modifying client frontend code.
 *   2. Re-distributing raw assets retains the original customer attribution.
 * ============================================================================
 */

import { createHash } from "node:crypto";

export interface WatermarkMetadata {
  customerId: string;
  licenseKey: string;
  albumId: string;
  generatedAt?: string;
}

/**
 * Embeds a forensic provenance header into a binary buffer (e.g. .mind file).
 * Prepends a non-destructive custom magic chunk:
 *   [0x41, 0x45, 0x54, 0x48] ("AETH") + [payloadLength (4 bytes)] + JSON string
 */
export function embedMindWatermark(mindBuffer: Buffer | Uint8Array, meta: WatermarkMetadata): Buffer {
  const payload = JSON.stringify({
    cid: meta.customerId,
    lic: meta.licenseKey.slice(0, 8) + "***",
    aid: meta.albumId,
    ts: meta.generatedAt || new Date().toISOString(),
    h: createHash("sha256").update(`${meta.customerId}:${meta.licenseKey}:${meta.albumId}`).digest("hex").slice(0, 16),
  });

  const payloadBuf = Buffer.from(payload, "utf-8");
  const headerBuf = Buffer.alloc(8 + payloadBuf.length);

  // Magic bytes "AETH"
  headerBuf.write("AETH", 0, 4, "ascii");
  // Payload length (32-bit uint big-endian)
  headerBuf.writeUInt32BE(payloadBuf.length, 4);
  // Payload
  payloadBuf.copy(headerBuf, 8);

  return Buffer.concat([headerBuf, Buffer.from(mindBuffer)]);
}

/**
 * Extracts embedded provenance metadata from a suspect .mind binary file.
 */
export function extractMindWatermark(buffer: Buffer | Uint8Array): WatermarkMetadata | null {
  const buf = Buffer.from(buffer);
  if (buf.length < 8) return null;

  // Check magic bytes "AETH"
  if (buf.toString("ascii", 0, 4) !== "AETH") {
    return null;
  }

  const payloadLength = buf.readUInt32BE(4);
  if (payloadLength > 4096 || buf.length < 8 + payloadLength) {
    return null;
  }

  try {
    const jsonStr = buf.toString("utf-8", 8, 8 + payloadLength);
    const parsed = JSON.parse(jsonStr);
    return {
      customerId: parsed.cid,
      licenseKey: parsed.lic,
      albumId: parsed.aid,
      generatedAt: parsed.ts,
    };
  } catch {
    return null;
  }
}

/**
 * Unified Storage Adapter Module.
 * Provides a single, configuration-driven object storage interface across both:
 *  - main (edge / Cloudflare R2 / $0)
 *  - self-hosted (private server / Docker / Cloudflare R2 or Supabase)
 */
import {
  S3Client,
  PutObjectCommand,
  GetObjectCommand,
  DeleteObjectCommand,
  HeadObjectCommand,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

const accountId = process.env.R2_ACCOUNT_ID || "";
const accessKeyId = process.env.R2_ACCESS_KEY_ID || "";
const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY || "";
export const R2_BUCKET = process.env.R2_BUCKET || "aether-ar-media";
export const R2_PUBLIC_BASE_URL = process.env.R2_PUBLIC_BASE_URL || "";

export type StorageProvider = "r2" | "supabase";

export function getStorageProvider(): StorageProvider {
  const customProvider = process.env.STORAGE_PROVIDER as StorageProvider | undefined;
  if (customProvider) return customProvider;
  if (accountId && accessKeyId && secretAccessKey) return "r2";
  return "supabase";
}

export function isR2Configured(): boolean {
  return Boolean(accountId && accessKeyId && secretAccessKey);
}

export function getR2Client(): S3Client {
  if (!isR2Configured()) {
    throw new Error(
      "Cloudflare R2 is not fully configured. Please set R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, and R2_SECRET_ACCESS_KEY.",
    );
  }
  return new S3Client({
    region: "auto",
    endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
    credentials: {
      accessKeyId,
      secretAccessKey,
    },
  });
}

/**
 * Generates a presigned upload URL for Cloudflare R2 (or fallback for Supabase).
 */
export async function createPresignedUploadUrl(
  path: string,
  contentType?: string,
  expiresInSeconds = 900,
): Promise<{ signedUrl: string; token: string; path: string; provider: StorageProvider }> {
  const provider = getStorageProvider();

  if (provider === "r2") {
    const client = getR2Client();
    const command = new PutObjectCommand({
      Bucket: R2_BUCKET,
      Key: path,
      ContentType: contentType || "application/octet-stream",
    });
    const signedUrl = await getSignedUrl(client, command, { expiresIn: expiresInSeconds });
    return { signedUrl, token: "", path, provider: "r2" };
  }

  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  const { data: signed, error } = await supabaseAdmin.storage
    .from("ar-media")
    .createSignedUploadUrl(path, { upsert: true });
  if (error) throw new Error(error.message);
  return { ...signed, provider: "supabase" };
}

/**
 * Generates a presigned download URL for media retrieval.
 */
export async function createPresignedDownloadUrl(
  path: string,
  expiresInSeconds = 900,
): Promise<string | null> {
  const provider = getStorageProvider();

  if (provider === "r2") {
    if (R2_PUBLIC_BASE_URL) {
      const cleanBase = R2_PUBLIC_BASE_URL.replace(/\/+$/, "");
      const cleanPath = path.replace(/^\/+/, "");
      return `${cleanBase}/${cleanPath}`;
    }
    const client = getR2Client();
    const command = new GetObjectCommand({
      Bucket: R2_BUCKET,
      Key: path,
    });
    return getSignedUrl(client, command, { expiresIn: expiresInSeconds });
  }

  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  const { data } = await supabaseAdmin.storage
    .from("ar-media")
    .createSignedUrl(path, expiresInSeconds);
  return data?.signedUrl ?? null;
}

/**
 * Retrieves object size and content type metadata.
 */
export async function getStorageObjectMetadata(
  path: string,
): Promise<{ size: number; contentType?: string } | null> {
  const provider = getStorageProvider();

  if (provider === "r2") {
    try {
      const client = getR2Client();
      const command = new HeadObjectCommand({
        Bucket: R2_BUCKET,
        Key: path,
      });
      const res = await client.send(command);
      return {
        size: res.ContentLength ?? 0,
        contentType: res.ContentType,
      };
    } catch {
      return null;
    }
  }

  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  const slash = path.lastIndexOf("/");
  const folder = slash === -1 ? "" : path.slice(0, slash);
  const name = slash === -1 ? path : path.slice(slash + 1);

  const { data: rows } = await supabaseAdmin.storage
    .from("ar-media")
    .list(folder, { search: name, limit: 1 });
  const size = (rows?.[0] as any)?.metadata?.size as number | undefined;
  return size != null ? { size } : null;
}

/**
 * Deletes an object from media storage.
 */
export async function deleteStorageObject(path: string): Promise<void> {
  const provider = getStorageProvider();

  if (provider === "r2") {
    const client = getR2Client();
    const command = new DeleteObjectCommand({
      Bucket: R2_BUCKET,
      Key: path,
    });
    await client.send(command);
    return;
  }

  const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
  await supabaseAdmin.storage.from("ar-media").remove([path]);
}

/**
 * ============================================================================
 * AETHER AR — ENTERPRISE UPLOAD SECURITY & MAGIC-BYTE VALIDATOR
 * ============================================================================
 * 
 * Verifies file signatures (magic bytes), strictly whitelists MIME types
 * and file extensions, checks max payload sizes, and sanitizes filenames
 * to prevent malicious executable injection, polyglot files, and directory traversal.
 * ============================================================================
 */

export const MAX_FILE_SIZE_BYTES = 50 * 1024 * 1024; // 50 MB

export const ALLOWED_EXTENSIONS = new Set(["jpg", "jpeg", "png", "mp4", "webm", "mind", "glb"]);

export const ALLOWED_MIME_TYPES = new Set([
  "image/jpeg",
  "image/png",
  "video/mp4",
  "video/webm",
  "application/octet-stream",
  "model/gltf-binary",
]);

/**
 * Validates the binary magic bytes (file signature) of a buffer.
 */
export function validateMagicBytes(buffer: Uint8Array, extension: string): boolean {
  if (buffer.length < 4) return false;

  const hex = Array.from(buffer.slice(0, 8))
    .map((b) => b.toString(16).padStart(2, "0").toUpperCase())
    .join(" ");

  switch (extension.toLowerCase()) {
    case "png":
      // PNG magic: 89 50 4E 47
      return hex.startsWith("89 50 4E 47");

    case "jpg":
    case "jpeg":
      // JPEG magic: FF D8 FF
      return hex.startsWith("FF D8 FF");

    case "mp4":
      // MP4 ISO Base Media file (ftyp box usually at offset 4)
      if (buffer.length >= 8) {
        const ftyp = String.fromCharCode(...buffer.slice(4, 8));
        return ftyp === "ftyp";
      }
      return false;

    case "webm":
      // WebM EBML header: 1A 45 DF A3
      return hex.startsWith("1A 45 DF A3");

    case "glb":
      // GLB (Binary glTF 2.0): magic = 0x67 0x6C 0x54 0x46 ("glTF")
      // Spec: https://registry.khronos.org/glTF/specs/2.0/glTF-2.0.html#binary-gltf-layout
      return (
        buffer[0] === 0x67 &&
        buffer[1] === 0x6c &&
        buffer[2] === 0x54 &&
        buffer[3] === 0x46
      );

    case "mind":
      // MindAR compiled target (.mind): the format begins with the ASCII
      // string "MIND" (0x4D 0x49 0x4E 0x44) followed by a version varint.
      // Source: https://github.com/hiukim/mind-ar-js internal format docs.
      return (
        buffer[0] === 0x4d &&
        buffer[1] === 0x49 &&
        buffer[2] === 0x4e &&
        buffer[3] === 0x44
      );

    case "bin":
      // Generic binary — no magic defined; accept without check.
      return true;

    default:
      return false;
  }
}

/**
 * Sanitizes a client-provided filename, stripping directory traversal characters.
 */
export function sanitizeFilename(filename: string): string {
  const base = filename
    .replace(/^.*[\\\/]/, "") // strip leading paths
    .replace(/[^a-zA-Z0-9._-]/g, "_"); // replace dangerous chars
  const ext = base.split(".").pop()?.toLowerCase() || "bin";

  if (!ALLOWED_EXTENSIONS.has(ext)) {
    throw new Error(`Disallowed file extension: .${ext}`);
  }

  return `${crypto.randomUUID()}.${ext}`;
}

/**
 * Comprehensive pre-upload security check.
 */
export async function validateUploadPayload(
  file: { name: string; type: string; size: number },
  buffer?: Uint8Array,
): Promise<{ ok: true; sanitizedName: string } | { ok: false; error: string }> {
  // 1. Size check
  if (file.size > MAX_FILE_SIZE_BYTES) {
    return { ok: false, error: `File size exceeds the 50 MB limit (${(file.size / (1024 * 1024)).toFixed(1)} MB)` };
  }

  // 2. Extension check
  const ext = file.name.split(".").pop()?.toLowerCase() || "";
  if (!ALLOWED_EXTENSIONS.has(ext)) {
    return { ok: false, error: `Disallowed file extension: .${ext}. Allowed: ${Array.from(ALLOWED_EXTENSIONS).join(", ")}` };
  }

  // 3. MIME type check
  if (file.type && !ALLOWED_MIME_TYPES.has(file.type)) {
    return { ok: false, error: `Disallowed MIME type: ${file.type}` };
  }

  // 4. Magic byte inspection if buffer available
  if (buffer && !validateMagicBytes(buffer, ext)) {
    return { ok: false, error: `File content does not match expected format for .${ext}` };
  }

  // 5. Enterprise Virus Scan Hook Placeholder
  // e.g., await scanWithClamAV(buffer);

  return { ok: true, sanitizedName: sanitizeFilename(file.name) };
}

import { signMediaUpload, enforceMediaSize } from "@/lib/experiences.functions";
import { supabase } from "@/integrations/supabase/client";
import { MAX_UPLOAD_BYTES, formatBytes } from "@/lib/video-compress";

export interface UploadProgress {
  stage: "compressing" | "uploading";
  percent: number;
  note?: string;
}

/**
 * Uploads a file/blob to the private ar-media bucket and returns its path.
 * Videos are compressed in the browser (<=1080p H.264/AAC MP4) before upload;
 * if compression is unavailable the original is used when it fits the limit.
 */
export async function uploadToArMedia(
  file: File | Blob,
  prefix: string,
  filename?: string,
  onProgress?: (p: UploadProgress) => void,
): Promise<string> {
  const name = filename ?? (file instanceof File ? file.name : "asset.bin");
  let payload: File | Blob = file;
  let uploadName = name;

  if (file instanceof File && file.type.startsWith("video/")) {
    const { compressVideo } = await import("@/lib/video-compress");
    const result = await compressVideo(file, (p) =>
      onProgress?.({
        stage: "compressing",
        percent: p.stage === "compressing" ? p.percent : 0,
        note: p.multithreaded ? undefined : "single-threaded — this may take longer",
      }),
    );
    if (!result.fellBack) {
      payload = result.file;
      uploadName = result.file.name;
    } else if (file.size > MAX_UPLOAD_BYTES) {
      throw new Error(
        `Couldn't compress this video (${result.reason ?? "unknown error"}) and the original is ${formatBytes(
          file.size,
        )} — over the 50 MB limit.`,
      );
    }
  }

  if (payload.size > MAX_UPLOAD_BYTES) {
    throw new Error(`${formatBytes(payload.size)} exceeds the 50 MB upload limit.`);
  }

  onProgress?.({ stage: "uploading", percent: 0 });
  const ext = uploadName.split(".").pop() || "bin";
  const path = `${prefix}/${crypto.randomUUID()}.${ext}`;
  const signed = await signMediaUpload({
    data: { path, upsert: true, size: payload.size },
  });

  if ((signed as any).provider === "r2" || (signed as any).signedUrl?.includes(".r2.cloudflarestorage.com")) {
    const res = await fetch((signed as any).signedUrl, {
      method: "PUT",
      headers: {
        "Content-Type": payload.type || "application/octet-stream",
      },
      body: payload,
    });
    if (!res.ok) {
      throw new Error(`Cloudflare R2 upload failed (${res.status} ${res.statusText})`);
    }
  } else {
    const { error } = await supabase.storage
      .from("ar-media")
      .uploadToSignedUrl(signed.path, signed.token, payload, {
        contentType: payload.type || "application/octet-stream",
        upsert: true,
      });
    if (error) throw error;
  }
  onProgress?.({ stage: "uploading", percent: 100 });

  // Server-side backstop — deletes the object if it exceeds the hard limit.
  await enforceMediaSize({ data: { path: signed.path } });

  return signed.path;
}

/**
 * Upload authorisation helpers.
 *
 * Every client-facing upload goes through a service-role signed upload URL, so
 * the private `ar-media` bucket needs no per-user storage.objects policy. The
 * ownership boundary lives here instead:
 *
 *  - admins may upload anywhere in the bucket;
 *  - approved editors may only upload inside their own `u/<user_id>/` prefix.
 *
 * Paths are namespaced server-side, so a client can never choose someone
 * else's folder, and `enforceMediaSize` re-checks the prefix before it records
 * the object or deletes it.
 */
import type { SupabaseClient } from "@supabase/supabase-js";

export type Uploader = { userId: string; isAdmin: boolean };

/** Throws unless the caller is an admin, or an approved editor. */
export async function authorizeUploader(
  supabase: SupabaseClient<any, any, any>,
  userId: string,
): Promise<Uploader> {
  const [{ data: roles }, { data: profile }] = await Promise.all([
    supabase.from("user_roles").select("role").eq("user_id", userId),
    supabase.from("profiles").select("approval_status").eq("id", userId).maybeSingle(),
  ]);

  const list = (roles ?? []) as Array<{ role: string }>;
  const isAdmin = list.some((r) => r.role === "admin");
  if (isAdmin) return { userId, isAdmin: true };

  const isEditor = list.some((r) => r.role === "editor");
  const approved = (profile as { approval_status?: string } | null)?.approval_status === "approved";

  if (!isEditor || !approved) {
    throw new Error(
      "Your account isn't approved for uploads yet. Ask an administrator to approve it.",
    );
  }
  return { userId, isAdmin: false };
}

const SAFE_SEGMENT = /^[A-Za-z0-9._-]+$/;

/**
 * Rewrites a client-supplied path into the caller's own namespace and strips
 * traversal attempts. Admins keep their existing flat paths for backwards
 * compatibility with content uploaded before namespacing.
 */
export function scopeUploadPath(uploader: Uploader, requested: string): string {
  const segments = requested
    .split("/")
    .map((s) => s.trim())
    .filter((s) => s.length > 0 && s !== "." && s !== "..");

  if (segments.length === 0 || !segments.every((s) => SAFE_SEGMENT.test(s))) {
    throw new Error("Invalid upload path");
  }

  // Never let a caller address another user's namespace.
  if (segments[0] === "u") segments.splice(0, 2);
  const clean = segments.join("/");
  if (!clean) throw new Error("Invalid upload path");

  return uploader.isAdmin ? clean : `u/${uploader.userId}/${clean}`;
}

/** True when this caller is allowed to act on an already-stored object path. */
export function ownsUploadPath(uploader: Uploader, path: string): boolean {
  return uploader.isAdmin || path.startsWith(`u/${uploader.userId}/`);
}

/**
 * Browser-side video compression with ffmpeg.wasm.
 *
 * Runs entirely off the main thread: @ffmpeg/ffmpeg v0.12 spawns its own
 * Web Worker and the wasm core executes inside it, so the admin UI stays
 * responsive while encoding.
 *
 * Threading: the multi-threaded core needs SharedArrayBuffer, which requires
 * cross-origin isolation (COOP: same-origin + COEP: require-corp). We do not
 * force COEP on the whole app because it would break the third-party CDN and
 * storage resources the AR viewer loads. Instead we detect isolation at
 * runtime and transparently fall back to the single-threaded core, warning
 * the admin that encoding will take longer.
 *
 * This module is browser-only — import it lazily from event handlers.
 */

const CORE_VERSION = "0.12.10";
const MT_BASE = `https://cdn.jsdelivr.net/npm/@ffmpeg/core-mt@${CORE_VERSION}/dist/umd`;
const ST_BASE = `https://cdn.jsdelivr.net/npm/@ffmpeg/core@${CORE_VERSION}/dist/umd`;

/** Hard server-side cap; mirrored here so the UI can explain rejections early. */
export const MAX_UPLOAD_BYTES = 50 * 1024 * 1024;

export const COMPRESSION_TIMEOUT_MS = 90_000;

export type CompressStage = "probing" | "loading" | "compressing";

export interface CompressProgress {
  stage: CompressStage;
  /** 0-100 */
  percent: number;
  multithreaded: boolean;
}

export interface CompressResult {
  file: File;
  originalBytes: number;
  compressedBytes: number;
  /** True when compression was skipped/failed and the original is returned. */
  fellBack: boolean;
  reason?: string;
  multithreaded: boolean;
}

export function canUseMultithread(): boolean {
  return (
    typeof SharedArrayBuffer !== "undefined" &&
    typeof crossOriginIsolated !== "undefined" &&
    crossOriginIsolated === true
  );
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  const units = ["KB", "MB", "GB"];
  let v = bytes / 1024;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i += 1;
  }
  return `${v < 10 ? v.toFixed(1) : Math.round(v)} ${units[i]}`;
}

/** Reads duration + whether the clip carries an audio track. */
async function probe(file: File): Promise<{ duration: number; hasAudio: boolean }> {
  const url = URL.createObjectURL(file);
  try {
    const video = document.createElement("video");
    video.preload = "metadata";
    video.muted = true;
    video.src = url;
    const duration = await new Promise<number>((resolve, reject) => {
      const t = setTimeout(() => reject(new Error("Could not read video metadata")), 15_000);
      video.onloadedmetadata = () => {
        clearTimeout(t);
        resolve(Number.isFinite(video.duration) ? video.duration : 0);
      };
      video.onerror = () => {
        clearTimeout(t);
        reject(new Error("Unsupported or corrupt video file"));
      };
    });
    const anyVideo = video as HTMLVideoElement & {
      mozHasAudio?: boolean;
      webkitAudioDecodedByteCount?: number;
      audioTracks?: { length: number };
    };
    const hasAudio =
      anyVideo.mozHasAudio === true ||
      (anyVideo.webkitAudioDecodedByteCount ?? 0) > 0 ||
      (anyVideo.audioTracks?.length ?? 0) > 0 ||
      // Metadata alone often can't tell; assume audio exists and let ffmpeg
      // decide — `-c:a aac` is a no-op when there is no audio stream.
      true;
    return { duration, hasAudio };
  } finally {
    URL.revokeObjectURL(url);
  }
}

/** bitrate_kbps = (35 × 8192 / duration) − 128, floored at 2000 kbps. */
export function targetBitrateKbps(durationSeconds: number): number {
  if (!durationSeconds || durationSeconds <= 0) return 4000;
  const raw = (35 * 8192) / durationSeconds - 128;
  return Math.max(2000, Math.min(12_000, Math.round(raw)));
}

let ffmpegSingleton: any = null;
let loadedMt = false;

async function getFFmpeg(mt: boolean, onLog?: (m: string) => void) {
  const { FFmpeg } = await import("@ffmpeg/ffmpeg");
  const { toBlobURL } = await import("@ffmpeg/util");

  if (ffmpegSingleton && loadedMt === mt) return ffmpegSingleton;

  const base = mt ? MT_BASE : ST_BASE;
  const ffmpeg = new FFmpeg();
  if (onLog) ffmpeg.on("log", ({ message }: { message: string }) => onLog(message));

  await ffmpeg.load({
    coreURL: await toBlobURL(`${base}/ffmpeg-core.js`, "text/javascript"),
    wasmURL: await toBlobURL(`${base}/ffmpeg-core.wasm`, "application/wasm"),
    ...(mt
      ? { workerURL: await toBlobURL(`${base}/ffmpeg-core.worker.js`, "text/javascript") }
      : {}),
  });

  ffmpegSingleton = ffmpeg;
  loadedMt = mt;
  return ffmpeg;
}

/**
 * Compresses a video to <=1080p H.264/AAC MP4.
 * Never throws for encoding problems — returns the original file with
 * `fellBack: true` so the caller can decide whether the raw file is small
 * enough to upload as-is.
 */
export async function compressVideo(
  file: File,
  onProgress?: (p: CompressProgress) => void,
  opts?: { keepAudio?: boolean; timeoutMs?: number },
): Promise<CompressResult> {
  const mt = canUseMultithread();
  const originalBytes = file.size;
  const emit = (stage: CompressStage, percent: number) =>
    onProgress?.({
      stage,
      percent: Math.max(0, Math.min(100, Math.round(percent))),
      multithreaded: mt,
    });

  const bail = (reason: string): CompressResult => ({
    file,
    originalBytes,
    compressedBytes: originalBytes,
    fellBack: true,
    reason,
    multithreaded: mt,
  });

  let duration = 0;
  let hasAudio = true;
  try {
    emit("probing", 0);
    const p = await probe(file);
    duration = p.duration;
    hasAudio = p.hasAudio;
  } catch (e: any) {
    return bail(e?.message ?? "Could not read this video");
  }

  const keepAudio = opts?.keepAudio ?? hasAudio;
  const bitrate = targetBitrateKbps(duration);

  let ffmpeg: any;
  try {
    emit("loading", 0);
    ffmpeg = await getFFmpeg(mt, undefined);
  } catch {
    return bail("Compression engine unavailable in this browser");
  }

  const inName = "input" + (file.name.match(/\.[a-z0-9]+$/i)?.[0] ?? ".mp4");
  const outName = "output.mp4";
  let timedOut = false;
  const timeout = setTimeout(() => {
    timedOut = true;
    try {
      ffmpeg.terminate();
    } catch {
      /* already gone */
    }
    ffmpegSingleton = null;
  }, opts?.timeoutMs ?? COMPRESSION_TIMEOUT_MS);

  try {
    const { fetchFile } = await import("@ffmpeg/util");
    await ffmpeg.writeFile(inName, await fetchFile(file));

    const onProg = ({ progress }: { progress: number }) => emit("compressing", progress * 100);
    ffmpeg.on("progress", onProg);

    // Downscale so neither edge exceeds 1920x1080 while keeping aspect ratio
    // (portrait clips are constrained by their shorter edge automatically).
    const scale =
      "scale='if(gt(iw/ih,16/9),min(1920,iw),-2)':'if(gt(iw/ih,16/9),-2,min(1080,ih))'," +
      "scale=trunc(iw/2)*2:trunc(ih/2)*2";

    const args = [
      "-i",
      inName,
      "-vf",
      scale,
      "-c:v",
      "libx264",
      "-preset",
      "veryfast",
      "-profile:v",
      "high",
      "-pix_fmt",
      "yuv420p",
      "-b:v",
      `${bitrate}k`,
      "-maxrate",
      `${Math.round(bitrate * 1.5)}k`,
      "-bufsize",
      `${bitrate * 2}k`,
      "-movflags",
      "+faststart",
      ...(keepAudio ? ["-c:a", "aac", "-b:a", "128k"] : ["-an"]),
      outName,
    ];

    const code = await ffmpeg.exec(args);
    ffmpeg.off?.("progress", onProg);
    if (timedOut) return bail("Compression timed out");
    if (code !== 0) return bail("Compression failed");

    const out = (await ffmpeg.readFile(outName)) as Uint8Array;
    await ffmpeg.deleteFile(inName).catch(() => {});
    await ffmpeg.deleteFile(outName).catch(() => {});

    if (!out || out.byteLength === 0) return bail("Compression produced an empty file");

    const buffer = new Uint8Array(out).slice().buffer as ArrayBuffer;
    const compressed = new File([buffer], file.name.replace(/\.[a-z0-9]+$/i, "") + ".mp4", {
      type: "video/mp4",
    });

    // Never hand back something bigger than the source.
    if (compressed.size >= originalBytes) {
      return { ...bail("Original was already smaller"), fellBack: true };
    }

    emit("compressing", 100);
    return {
      file: compressed,
      originalBytes,
      compressedBytes: compressed.size,
      fellBack: false,
      multithreaded: mt,
    };
  } catch (e: any) {
    return bail(timedOut ? "Compression timed out" : (e?.message ?? "Compression failed"));
  } finally {
    clearTimeout(timeout);
  }
}

import { createFileRoute, redirect } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import {
  listActivations,
  revokeActivation,
  forceReleaseActivation,
} from "@/lib/licenses.functions";
import { assertAdmin } from "@/lib/admin.functions";
import { toast } from "sonner";
import { QueryState } from "@/components/QueryState";
import { ShieldOff, Unlock, X, ScrollText } from "lucide-react";
import { useState } from "react";

export const Route = createFileRoute("/_authenticated/dashboard/activations")({
  beforeLoad: async () => {
    const ok = await assertAdmin()
      .then(() => true)
      .catch(() => false);
    if (!ok) {
      toast.error("You don't have access to device activations.");
      throw redirect({ to: "/dashboard" });
    }
  },
  component: ActivationsPage,
});

function ActivationsPage() {
  const qc = useQueryClient();
  const listFn = useServerFn(listActivations);
  const revokeFn = useServerFn(revokeActivation);
  const {
    data: activations = [],
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: ["activations"],
    queryFn: () => listFn(),
    staleTime: 30_000,
  });

  const releaseFn = useServerFn(forceReleaseActivation);
  const [target, setTarget] = useState<any | null>(null);
  const [password, setPassword] = useState("");
  const [reason, setReason] = useState("");
  const [lastEntry, setLastEntry] = useState<any | null>(null);

  const releaseMut = useMutation({
    mutationFn: () => releaseFn({ data: { id: target.id, password, reason: reason || undefined } }),
    onSuccess: (entry) => {
      qc.invalidateQueries({ queryKey: ["activations"] });
      setLastEntry(entry);
      setTarget(null);
      setPassword("");
      setReason("");
      toast.success("Device slot released — cooldown cleared.");
    },
    onError: (e: Error) => toast.error(e.message),
  });

  const revokeMut = useMutation({
    mutationFn: (id: string) => revokeFn({ data: { id } }),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ["activations"] });
      toast.success("Revoked");
    },
  });

  return (
    <div className="p-8 max-w-6xl">
      <h1 className="text-3xl font-serif italic mb-1">Activations</h1>
      <p className="text-sm text-muted-foreground mb-8">
        Deployment instances that have activated a license.
      </p>

      <QueryState
        isLoading={isLoading}
        error={error}
        onRetry={() => refetch()}
        label="activations"
      />

      <div className="rounded-2xl border border-border/60 bg-card/40 overflow-hidden">
        <table className="w-full text-sm">
          <thead className="bg-muted/50 text-xs uppercase text-muted-foreground">
            <tr>
              <th className="text-left px-4 py-3">Client / License</th>
              <th className="text-left px-4 py-3">Deployment</th>
              <th className="text-left px-4 py-3">Fingerprint</th>
              <th className="text-left px-4 py-3">Last seen</th>
              <th className="text-left px-4 py-3">Status</th>
              <th />
            </tr>
          </thead>
          <tbody className="divide-y divide-border/60">
            {activations.map((a: any) => (
              <tr key={a.id}>
                <td className="px-4 py-3">
                  <div>{a.licenses?.client_name}</div>
                  <div className="text-xs font-mono text-muted-foreground">
                    {a.licenses?.license_key}
                  </div>
                </td>
                <td className="px-4 py-3">
                  <div>{a.deployment_domain || "—"}</div>
                  <div className="text-xs text-muted-foreground">{a.deployment_platform}</div>
                </td>
                <td className="px-4 py-3 font-mono text-xs">{a.fingerprint.slice(0, 16)}…</td>
                <td className="px-4 py-3 text-xs">{new Date(a.last_seen_at).toLocaleString()}</td>
                <td className="px-4 py-3">
                  {a.revoked_at ? (
                    <span className="text-xs text-destructive">Revoked</span>
                  ) : (
                    <span className="text-xs text-primary">Active</span>
                  )}
                </td>
                <td className="px-4 py-3">
                  <div className="flex items-center gap-2">
                    {!a.revoked_at && (
                      <button
                        onClick={() => confirm("Revoke this activation?") && revokeMut.mutate(a.id)}
                        className="inline-flex items-center gap-1 text-xs px-2 py-1 rounded-md border border-border hover:bg-destructive/10 text-destructive"
                      >
                        <ShieldOff className="h-3 w-3" /> Revoke
                      </button>
                    )}
                    <button
                      onClick={() => {
                        setTarget(a);
                        setPassword("");
                        setReason("");
                      }}
                      className="inline-flex items-center gap-1 text-xs px-2 py-1 rounded-md border border-border hover:bg-muted"
                      title="Free this slot immediately and clear the 12h cooldown"
                    >
                      <Unlock className="h-3 w-3" /> Force release
                    </button>
                  </div>
                </td>
              </tr>
            ))}
            {activations.length === 0 && (
              <tr>
                <td colSpan={6} className="px-4 py-12 text-center text-muted-foreground">
                  No activations yet.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {lastEntry && (
        <div className="mt-6 rounded-2xl border border-border/60 bg-card/40 p-4">
          <div className="flex items-center gap-2 text-sm font-medium mb-2">
            <ScrollText className="h-4 w-4 text-primary" /> Audit entry recorded
          </div>
          <dl className="grid grid-cols-[auto_1fr] gap-x-4 gap-y-1 text-xs text-muted-foreground">
            <dt>Action</dt>
            <dd className="font-mono text-foreground">{lastEntry.action}</dd>
            <dt>Activation</dt>
            <dd className="font-mono">{lastEntry.target_id}</dd>
            <dt>When</dt>
            <dd>{new Date(lastEntry.created_at).toLocaleString()}</dd>
            <dt>Details</dt>
            <dd className="font-mono break-all">{JSON.stringify(lastEntry.metadata)}</dd>
          </dl>
        </div>
      )}

      {target && (
        <div className="fixed inset-0 z-50 bg-black/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="w-full max-w-md rounded-2xl border border-border/60 bg-card p-6">
            <div className="flex items-center justify-between mb-2">
              <h2 className="text-xl font-serif italic">Force-release device</h2>
              <button onClick={() => setTarget(null)} aria-label="Close">
                <X className="h-4 w-4" />
              </button>
            </div>
            <p className="text-sm text-muted-foreground mb-4">
              This frees the {target.device_class} slot on{" "}
              <span className="text-foreground">{target.licenses?.client_name}</span> straight away
              and skips the 12-hour cooldown. Confirm with your password.
            </p>
            <form
              onSubmit={(e) => {
                e.preventDefault();
                releaseMut.mutate();
              }}
              className="space-y-3"
            >
              <input
                required
                type="password"
                autoComplete="current-password"
                placeholder="Your password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full rounded-md border border-border bg-background px-3 py-2 text-sm"
              />
              <input
                placeholder="Reason (kept in the audit log)"
                value={reason}
                onChange={(e) => setReason(e.target.value)}
                className="w-full rounded-md border border-border bg-background px-3 py-2 text-sm"
              />
              <button
                disabled={releaseMut.isPending}
                className="w-full rounded-md bg-primary text-primary-foreground px-4 py-2 text-sm font-medium hover:bg-primary/90 disabled:opacity-50"
              >
                {releaseMut.isPending ? "Releasing…" : "Confirm release"}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

