                <option value="image">Image</option>
              </select>
            </label>
            <label className="text-sm flex items-center gap-2 mt-6">
              <input
                type="checkbox"
                checked={value.autoplay}
                onChange={(e) => set("autoplay", e.target.checked)}
              />
              Autoplay
            </label>
            <label className="text-sm flex items-center gap-2 mt-6">
              <input
                type="checkbox"
                checked={value.loop_playback}
                onChange={(e) => set("loop_playback", e.target.checked)}
              />
              Loop
            </label>
          </div>
          <label className="text-sm flex items-center gap-2">
            <input
              type="checkbox"
              checked={value.published}
              onChange={(e) => set("published", e.target.checked)}
            />
            Published (visible to public)
          </label>
          <label className="text-sm flex items-center gap-2">
            <input
              type="checkbox"
              checked={value.show_in_gallery}
              onChange={(e) => set("show_in_gallery", e.target.checked)}
            />
            Show in the public gallery (off by default — PIN-protected items are never listed)
          </label>
          {errorText && (
            <div className="rounded-md border border-destructive/50 bg-destructive/10 p-3">
              <div className="text-sm font-medium text-destructive">Save failed</div>
              <pre className="mt-1 max-h-40 overflow-auto whitespace-pre-wrap break-words text-xs text-destructive/90">
                {errorText}
              </pre>
            </div>
          )}
          <div className="flex justify-end gap-2 pt-4 border-t border-border/60">
            <button
              type="button"
              onClick={onCancel}
              className="px-4 py-2 text-sm rounded-md border border-border hover:bg-accent"
            >
              Cancel
            </button>
            <button
              disabled={saving}
              type="submit"
              className="px-4 py-2 text-sm rounded-md bg-primary text-primary-foreground hover:bg-primary/90 disabled:opacity-50"
            >
              {saving ? "Saving…" : "Save"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

import { createFileRoute, redirect } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
