  });

  const renameMut = useMutation({
    mutationFn: (v: { id: string; name: string }) => rename({ data: v }),
    onSuccess: invalidate,
    onError: (e: any) => toast.error(e.message ?? "Rename failed"),
  });

  const deleteMut = useMutation({
    mutationFn: (id: string) => remove({ data: { id } }),
    onSuccess: () => {
      toast.success("Project removed — its content is now unfiled");
      invalidate();
    },
    onError: (e: any) => toast.error(e.message ?? "Delete failed"),
  });

  const assignMut = useMutation({
    mutationFn: (v: { kind: "album" | "experience"; id: string; project_id: string | null }) =>
      assign({ data: v }),
    onSuccess: invalidate,
    onError: (e: any) => toast.error(e.message ?? "Could not move item"),
  });

  const projects = query.data?.projects ?? [];
  const albums = (query.data?.albums ?? []) as Item[];
  const experiences = (query.data?.experiences ?? []) as Item[];

  const picker = (kind: "album" | "experience", item: Item) => (
    <select
      value={item.project_id ?? ""}
      onChange={(e) =>
        assignMut.mutate({
          kind,
          id: item.id,
          project_id: e.target.value || null,
        })
      }
      className="rounded-md border border-border/60 bg-background px-2 py-1 text-xs"
    >
      <option value="">Unfiled</option>
      {projects.map((p: any) => (
        <option key={p.id} value={p.id}>
          {p.name}
        </option>
      ))}
    </select>
  );

  const row = (kind: "album" | "experience", item: Item) => (
    <li
      key={item.id}
      className="flex items-center justify-between gap-3 rounded-lg border border-border/50 bg-card/30 px-3 py-2"
    >
      <div className="flex min-w-0 items-center gap-2">
        {kind === "album" ? (
          <Images className="h-4 w-4 shrink-0 text-muted-foreground" />
        ) : (
          <Boxes className="h-4 w-4 shrink-0 text-muted-foreground" />
        )}
        <span className="truncate text-sm">{item.title}</span>
        {!item.published && (
          <span className="rounded-full bg-muted px-2 py-0.5 text-[10px] text-muted-foreground">
            draft
          </span>
        )}
      </div>
      {picker(kind, item)}
    </li>
  );

  return (
    <div className="p-6 md:p-8 space-y-8">
      <header className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="text-2xl font-serif italic">Projects</h1>
          <p className="text-sm text-muted-foreground">
            Folders for your clients — keep each wedding, event or brand campaign separate. Content
            stays private to your account.
          </p>
        </div>
        <form
          onSubmit={(e) => {
            e.preventDefault();
            if (name.trim()) createMut.mutate(name.trim());
          }}
          className="flex items-center gap-2"
        >
          <input
            value={name}
            onChange={(e) => setName(e.target.value)}
            placeholder="e.g. Sharma Wedding"
            className="rounded-md border border-border/60 bg-background px-3 py-2 text-sm"
          />
          <button
            type="submit"
            disabled={createMut.isPending}
            className="inline-flex items-center gap-2 rounded-md bg-primary px-3 py-2 text-sm text-primary-foreground disabled:opacity-60"
          >
            <FolderPlus className="h-4 w-4" /> New project
          </button>
        </form>
      </header>

      <QueryState
        isLoading={query.isLoading}
        error={query.error}
        onRetry={() => void query.refetch()}
      />

      {query.data && (
        <div className="space-y-6">
          {projects.map((p: any) => {
            const pa = albums.filter((a) => a.project_id === p.id);
            const pe = experiences.filter((x) => x.project_id === p.id);
            return (
              <section key={p.id} className="rounded-xl border border-border/60 bg-card/20 p-4">
                <div className="mb-3 flex items-center justify-between gap-3">
                  <div className="flex items-center gap-2">
                    <Folder className="h-4 w-4 text-primary" />
                    <h2 className="text-base font-medium">{p.name}</h2>
                    <span className="text-xs text-muted-foreground">
                      {pa.length} album{pa.length === 1 ? "" : "s"} · {pe.length} experience
                      {pe.length === 1 ? "" : "s"}
                    </span>
                  </div>
                  <div className="flex items-center gap-1">
                    <button
                      onClick={() => {
                        const next = window.prompt("Rename project", p.name);
                        if (next?.trim()) renameMut.mutate({ id: p.id, name: next.trim() });
                      }}
                      className="rounded-md p-2 text-muted-foreground hover:bg-accent"
                      aria-label="Rename project"
                    >
                      <Pencil className="h-4 w-4" />
                    </button>
                    <button
                      onClick={() => {
                        if (
                          window.confirm(
                            "Remove this project? Albums and experiences inside it are kept and become unfiled.",
                          )
                        )
                          deleteMut.mutate(p.id);
                      }}
                      className="rounded-md p-2 text-muted-foreground hover:bg-destructive/10 hover:text-destructive"
                      aria-label="Delete project"
                    >
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                </div>
                {pa.length + pe.length === 0 ? (
                  <p className="text-xs text-muted-foreground">
                    Nothing filed here yet — use the dropdowns below to move albums or experiences
                    into this project.
                  </p>
                ) : (
                  <ul className="space-y-2">
                    {pa.map((a) => row("album", a))}
                    {pe.map((x) => row("experience", x))}
                  </ul>
                )}
              </section>
            );
          })}

          <section className="rounded-xl border border-dashed border-border/60 p-4">
            <h2 className="mb-3 text-base font-medium">Unfiled</h2>
            {albums.filter((a) => !a.project_id).length +
              experiences.filter((x) => !x.project_id).length ===
            0 ? (
              <p className="text-xs text-muted-foreground">
                Everything is filed.{" "}
                <Link to="/dashboard/albums" className="underline">
                  Go to albums
                </Link>
              </p>
            ) : (
              <ul className="space-y-2">
                {albums.filter((a) => !a.project_id).map((a) => row("album", a))}
                {experiences.filter((x) => !x.project_id).map((x) => row("experience", x))}
              </ul>
            )}
          </section>
        </div>
      )}
    </div>
  );
}

import {
  createFileRoute,
  Link,
  Outlet,
  useNavigate,
  useRouteContext,
  useRouterState,
} from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useServerFn } from "@tanstack/react-start";
import { getDeploymentProfile } from "@/lib/deployment.functions";
import {
  Sparkles,
  LayoutDashboard,
  Boxes,
  Images,
  Key,
  ShieldCheck,
  LogOut,
  ScrollText,
  BarChart3,
  Target,
  UserCheck,
  FolderOpen,
  Activity,
  Package,
} from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/_authenticated/dashboard")({
  component: DashboardLayout,
});

function DashboardLayout() {
  const navigate = useNavigate();
  const qc = useQueryClient();
  const [email, setEmail] = useState<string>("");
  const { user, isAdmin } = useRouteContext({ from: "/_authenticated" });
  const pathname = useRouterState({ select: (s) => s.location.pathname });

  useEffect(() => {
    setEmail(user?.email ?? "");
  }, [user]);

  async function signOut() {
    await qc.cancelQueries();
    qc.clear();
    await supabase.auth.signOut();
    toast.success("Signed out");
    navigate({ to: "/auth", replace: true });
  }

  // Branch-aware features: a customer (client-app) build hides licensing,
  // approvals and diagnostics entirely, even for an admin account.
  const profileFn = useServerFn(getDeploymentProfile);
  const { data: profile } = useQuery({
    queryKey: ["deployment-profile"],
    queryFn: () => profileFn(),
    staleTime: Infinity,
  });
  const features = profile?.features;
  const can = (flag: keyof NonNullable<typeof features>) => !features || features[flag];

  const nav = [
    { to: "/dashboard", label: "Overview", icon: LayoutDashboard, exact: true },
    { to: "/dashboard/projects", label: "Projects", icon: FolderOpen },
    { to: "/dashboard/experiences", label: "AR Experiences", icon: Boxes },
    { to: "/dashboard/albums", label: "Albums", icon: Images },
    ...(can("catalog")
      ? [{ to: "/dashboard/catalogs", label: "Catalogs", icon: Package }]
      : []),
    ...(can("analytics")
      ? [
          { to: "/dashboard/analytics", label: "Analytics", icon: BarChart3 },
          { to: "/dashboard/marker-tests", label: "Marker Testing", icon: Target },
        ]
      : []),
    ...(isAdmin && can("approvals")
      ? [{ to: "/dashboard/approvals", label: "Approvals", icon: UserCheck }]
      : []),
    ...(isAdmin && can("licensing")
      ? [
          { to: "/dashboard/licenses", label: "Licenses", icon: Key },
          { to: "/dashboard/activations", label: "Activations", icon: ShieldCheck },
        ]
      : []),
    ...(isAdmin && can("diagnostics")
      ? [
          { to: "/dashboard/audit", label: "Audit Log", icon: ScrollText },
          { to: "/dashboard/diagnostics", label: "Diagnostics", icon: Activity },
        ]
      : []),
  ];

  return (
    <div className="min-h-screen bg-background text-foreground grid grid-rows-[auto_1fr] md:grid-rows-1 md:grid-cols-[240px_1fr]">
      <aside className="border-b md:border-b-0 md:border-r border-border/60 bg-card/20 backdrop-blur-xl flex flex-col md:min-h-screen">
        <Link to="/" className="flex items-center gap-2 px-6 h-16 border-b border-border/60">
          <Sparkles className="h-5 w-5 text-primary" />
          <span className="text-lg font-serif italic">Aether AR</span>
        </Link>
        <nav className="flex p-2 gap-1 overflow-x-auto md:flex-1 md:p-3 md:space-y-1 md:block">
          {nav.map(({ to, label, icon: Icon, exact }) => {
            const active = exact ? pathname === to : pathname.startsWith(to);
            return (
              <Link
                key={to}
                to={to}
                preload="intent"
                className={`flex shrink-0 items-center gap-2 md:gap-3 px-3 py-2 rounded-md text-sm transition-colors ${
                  active
                    ? "bg-primary/15 text-primary font-medium"
                    : "text-muted-foreground hover:bg-accent hover:text-foreground"
                }`}
              >
                <Icon className="h-4 w-4" />
                <span className="whitespace-nowrap">{label}</span>
              </Link>
            );
          })}
        </nav>
        <div className="p-3 border-t border-border/60">
          <div className="px-3 py-2 flex items-center justify-between gap-2">
            <span className="text-xs text-muted-foreground truncate">{email}</span>
            <span
              className={`shrink-0 text-[10px] uppercase tracking-wider px-2 py-0.5 rounded-full border ${
                isAdmin
                  ? "border-primary/40 bg-primary/10 text-primary"
                  : "border-border/60 text-muted-foreground"
              }`}
            >
              {isAdmin ? "Admin" : "Client"}
            </span>
          </div>
          <button
            onClick={signOut}
            className="w-full flex items-center gap-3 px-3 py-2 rounded-md text-sm text-muted-foreground hover:bg-accent hover:text-foreground transition-colors"
          >
            <LogOut className="h-4 w-4" />
            Sign out
          </button>
        </div>
      </aside>
      <main className="overflow-y-auto min-w-0">
        <Outlet />
      </main>
    </div>
  );
}

import { createFileRoute, useNavigate, useSearch } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { supabase } from "@/integrations/supabase/client";
import { toast } from "sonner";
import { ShieldCheck, Loader2 } from "lucide-react";
import { z } from "zod";

const searchSchema = z.object({ redirect: z.string().optional() });

export const Route = createFileRoute("/_authenticated/mfa")({
  validateSearch: searchSchema,
  component: MFAPage,
});

function MFAPage() {
  const navigate = useNavigate();
  const { redirect } = useSearch({ from: "/_authenticated/mfa" });
  const [mode, setMode] = useState<"loading" | "enroll" | "challenge">("loading");
  const [factorId, setFactorId] = useState<string | null>(null);
  const [qr, setQr] = useState<string | null>(null);
  const [secret, setSecret] = useState<string | null>(null);
  const [code, setCode] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    (async () => {
      const { data: factors } = await supabase.auth.mfa.listFactors();
      const verified = factors?.totp?.find((f) => f.status === "verified");
      if (verified) {
        setFactorId(verified.id);
        setMode("challenge");
        return;
      }
      // Enroll a new factor
      const { data, error } = await supabase.auth.mfa.enroll({ factorType: "totp" });
      if (error) {
        toast.error(error.message);
        return;
      }
      setFactorId(data.id);
      setQr(data.totp.qr_code);
      setSecret(data.totp.secret);
      setMode("enroll");
    })();
  }, []);

  async function verify() {
    if (!factorId) return;
    setBusy(true);
    try {
      const { data: challenge, error: chErr } = await supabase.auth.mfa.challenge({ factorId });
      if (chErr) throw chErr;
      const { error: vErr } = await supabase.auth.mfa.verify({
        factorId,
        challengeId: challenge.id,
        code: code.trim(),
      });
      if (vErr) throw vErr;
      toast.success("Two-factor verified");
      navigate({ to: redirect || "/dashboard" });
    } catch (e: any) {
      toast.error(e.message ?? "Verification failed");
    } finally {
      setBusy(false);
    }
  }

  if (mode === "loading") {
    return (
      <div className="min-h-screen grid place-items-center bg-background text-foreground">
        <Loader2 className="animate-spin h-6 w-6 text-muted-foreground" />
      </div>
    );
  }

  return (
    <div className="min-h-screen grid place-items-center bg-background text-foreground p-6">
      <div className="max-w-md w-full rounded-2xl border border-border/60 bg-card/40 p-8">
        <div className="flex items-center gap-3 mb-6">
          <ShieldCheck className="h-6 w-6 text-primary" />
          <h1 className="text-2xl font-serif italic">
            {mode === "enroll" ? "Enable two-factor" : "Enter your code"}
          </h1>
        </div>

        {mode === "enroll" && (
          <>
            <p className="text-sm text-muted-foreground mb-4">
              Admin accounts require TOTP. Scan this QR code with Google Authenticator, 1Password,
              or Authy — then enter the 6-digit code below.
            </p>
            {qr && (
              <img
                src={qr}
                alt="TOTP QR"
                className="w-48 h-48 mx-auto mb-3 rounded-md bg-white p-2"
              />
            )}
            {secret && (
              <p className="text-xs text-center text-muted-foreground mb-4">
                Or enter secret manually:{" "}
                <code className="font-mono text-foreground">{secret}</code>
              </p>
            )}
          </>
        )}

        {mode === "challenge" && (
          <p className="text-sm text-muted-foreground mb-4">
            Open your authenticator app and enter the current 6-digit code.
          </p>
        )}

        <input
          value={code}
          onChange={(e) => setCode(e.target.value.replace(/\D/g, "").slice(0, 6))}
          inputMode="numeric"
          placeholder="000000"
          className="w-full text-center text-2xl font-mono tracking-widest rounded-md border border-border bg-background px-3 py-3 mb-4"
        />

        <button
          onClick={verify}
          disabled={busy || code.length !== 6}
          className="w-full rounded-md bg-primary text-primary-foreground px-4 py-2 text-sm font-medium hover:bg-primary/90 disabled:opacity-50"
        >
          {busy ? "Verifying…" : mode === "enroll" ? "Enable 2FA" : "Verify"}
        </button>
      </div>
    </div>
  );
}

import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { useServerFn } from "@tanstack/react-start";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { getMyAccount } from "@/lib/account.functions";
import { Clock, Copy, LogOut, ShieldX, Sparkles } from "lucide-react";
import { toast } from "sonner";

export const Route = createFileRoute("/_authenticated/pending")({
  component: PendingPage,
});

function PendingPage() {
  const navigate = useNavigate();
  const qc = useQueryClient();
  const fetchAccount = useServerFn(getMyAccount);

  const { data, isLoading } = useQuery({
    queryKey: ["my-account"],
    queryFn: () => fetchAccount(),
    refetchInterval: 30_000,
  });

  const status = data?.profile?.approval_status ?? "pending";
  const license = data?.license ?? null;

  async function signOut() {
    await qc.cancelQueries();
    qc.clear();
    await supabase.auth.signOut();
    navigate({ to: "/auth", replace: true });
  }

  return (
    <div className="min-h-screen grid place-items-center px-6 py-16 bg-background text-foreground">
      <div className="w-full max-w-lg rounded-2xl border border-border/60 bg-card/30 backdrop-blur-xl p-8">
        <Link to="/" className="flex items-center gap-2 mb-8">
          <Sparkles className="h-5 w-5 text-primary" />
          <span className="text-lg font-serif italic">Aether AR</span>
        </Link>

        {status === "rejected" ? (
          <>
            <ShieldX className="h-8 w-8 text-destructive mb-4" />
            <h1 className="text-2xl font-serif mb-2">Account not approved</h1>
            <p className="text-sm text-muted-foreground">
              {data?.profile?.rejection_reason ||
                "An administrator declined access for this account. Reply to your onboarding email if you think this is a mistake."}
            </p>
          </>
        ) : status === "approved" ? (
          <>
            <h1 className="text-2xl font-serif mb-2">You're approved</h1>
            <p className="text-sm text-muted-foreground mb-6">
              Your workspace and licence are ready.
            </p>
            {license && <LicenseCard license={license} />}
            <Link
              to="/dashboard"
              className="mt-6 inline-flex rounded-full bg-primary text-primary-foreground px-5 py-2 text-sm font-medium"
            >
              Open dashboard
            </Link>
          </>
        ) : (
          <>
            <Clock className="h-8 w-8 text-primary mb-4" />
            <h1 className="text-2xl font-serif mb-2">Waiting for admin approval</h1>
            <p className="text-sm text-muted-foreground">
              Your account <span className="text-foreground">{data?.profile?.email}</span> was
              created successfully. An administrator has to approve it before you can publish AR
              experiences. Your licence key is issued automatically the moment you're approved —
              this page refreshes itself.
            </p>
            {isLoading && (
              <p className="mt-4 text-xs text-muted-foreground animate-pulse">
                Checking your status…
              </p>
            )}
          </>
        )}

        <button
          onClick={signOut}
          className="mt-8 flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground transition-colors"
        >
          <LogOut className="h-4 w-4" /> Sign out
        </button>
      </div>
    </div>
  );
}

function LicenseCard({ license }: { license: any }) {
  return (
    <div className="rounded-xl border border-border/60 bg-background/40 p-4">
      <p className="text-xs uppercase tracking-wider text-muted-foreground mb-2">
        Your licence key
      </p>
      <div className="flex items-center gap-2">
        <code className="text-sm break-all">{license.license_key}</code>
        <button
          onClick={() => {
            navigator.clipboard.writeText(license.license_key);
            toast.success("Licence key copied");
          }}
          className="shrink-0 rounded-md p-1.5 hover:bg-accent"
          aria-label="Copy licence key"
        >
          <Copy className="h-4 w-4" />
        </button>
      </div>
      <p className="mt-2 text-xs text-muted-foreground">
        {license.plan} · {license.max_activations} activation
        {license.max_activations === 1 ? "" : "s"} · {license.status}
      </p>
    </div>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { z } from "zod";
import { activate } from "@/lib/adapters/licence.server";
import { check } from "@/lib/adapters/ratelimit.server";
import { clientIp, json, serverDerivedOrigin } from "@/lib/licence-http";

/**
 * Note what is NOT in this schema: `originHost`. The origin is taken from the
 * request headers below — a body-declared origin is self-certification (§4.2).
 * `deviceFingerprint` IS accepted, but only as a support signal; device
 * identity is the server-minted `deviceSecret`.
 */
const Schema = z.object({
  licenceKey: z.string().min(10).max(200),
  platform: z.enum(["mobile", "desktop"]),
  buildId: z.string().max(200).optional(),
  assetDigest: z.string().max(200).optional(),
  deviceFingerprint: z.string().max(200).optional(),
  deviceSecret: z.string().max(200).optional(),
  capabilityTier: z.string().max(32).optional(),
  label: z.string().max(80).optional(),
});

export const Route = createFileRoute("/api/public/licence/activate")({
  server: {
    handlers: {
      OPTIONS: async ({ request }) => json({ ok: true }, 200, {}, request),
      POST: async ({ request }) => {
        let input: z.infer<typeof Schema>;
        try {
          input = Schema.parse(await request.json());
        } catch (e) {
          return json({ ok: false, error: e instanceof Error ? e.message : "BAD_REQUEST" }, 400, {}, request);
        }

        const ip = clientIp(request);
        const originHost = serverDerivedOrigin(request);

        // Activation is a mutation that allocates a device slot: it fails CLOSED
        // when the limiter store is down, so an outage is never a free-for-all.
        for (const [key, limit, win] of [
          [`licence:ip:${ip ?? "unknown"}`, 10, 60],
          [`licence:key:${input.licenceKey}`, 20, 3600],
        ] as const) {
          const { allowed, degraded } = await check(key, limit, win, { failMode: "closed" });
          if (!allowed) {
            return json(
              { ok: false, error: degraded ? "RATE_LIMITER_DOWN" : "RATE_LIMITED" },
              429,
              {},
              request,
              originHost,
            );
          }
        }

        const result = await activate({
          licenceKey: input.licenceKey,
          platform: input.platform,
          originHost,
          ip,
          userAgent: request.headers.get("user-agent"),
          attestation: { buildId: input.buildId, assetDigest: input.assetDigest },
          fingerprintSignal: input.deviceFingerprint ?? null,
          deviceSecret: input.deviceSecret ?? null,
          capabilityTier: input.capabilityTier ?? null,
          label: input.label ?? null,
        });

        if (!result.ok) return json({ ok: false, error: result.error }, result.status, {}, request, originHost);
        return json(
          {
            ok: true,
            token: result.token,
            plan: result.plan,
            features: result.features,
            expiresIn: result.expiresIn,
            graceHours: result.graceHours,
            deviceId: result.deviceId,
            // Shown exactly once. The client stores it; the server keeps only a hash.
            deviceSecret: result.deviceSecret,
          },
          200,
          {},
          request,
          originHost,
        );
      },
    },
  },
});

/**
 * CI on the `client-app` branch POSTs the signed asset manifest here after a
 * successful build, so heartbeats from that release can be validated.
 * Authenticated with a shared secret (RELEASE_MANIFEST_SECRET) AND verified
 * with Ed25519 signature before accepting.
 */
import { createFileRoute } from "@tanstack/react-router";
import { z } from "zod";
import { enforceRateLimit } from "@/lib/rate-limiter.middleware";
import { readEnv } from "@/lib/adapters/env.server";

const Schema = z.object({
  buildId: z.string().min(4).max(200),
  customerId: z.string().max(200).optional().default("universal"),
  assetDigest: z.string().min(32).max(200),
  releaseHash: z.string().min(32).max(200).optional(),
  signature: z.string().min(16).max(4000),
  files: z.array(z.object({
    path: z.string(),
    hash: z.string(),
  })).optional().default([]),
  branch: z.string().max(64).default("client-app"),
});

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json" },
  });
}

function timingSafeEqual(a: string, b: string) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

function b64ToBytes(b64: string) {
  const bin = atob(b64.replace(/-/g, "+").replace(/_/g, "/"));
  return Uint8Array.from(bin, (c) => c.charCodeAt(0));
}

async function verifyManifestSignature(
  buildId: string,
  customerId: string,
  releaseHash: string,
  signature: string
): Promise<boolean> {
  const pubJwkRaw = readEnv("LICENCE_PUBLIC_KEY_JWK") || readEnv("VITE_LICENCE_PUBLIC_KEY");
  const privJwkRaw = readEnv("LICENCE_PRIVATE_KEY_JWK");

  let jwk: JsonWebKey | null = null;
  if (pubJwkRaw) {
    try {
      jwk = typeof pubJwkRaw === "string" ? JSON.parse(pubJwkRaw) : pubJwkRaw;
    } catch {
      jwk = null;
    }
  } else if (privJwkRaw) {
    try {
      const priv = JSON.parse(privJwkRaw);
      jwk = { kty: priv.kty, crv: priv.crv, x: priv.x };
    } catch {
      jwk = null;
    }
  }

  if (!jwk) return true; // If no keys set on admin yet, skip crypto verification

  try {
    const key = await crypto.subtle.importKey(
      "jwk",
      jwk,
      { name: "Ed25519" },
      false,
      ["verify"]
    );
    const signMessage = new TextEncoder().encode(`${buildId}.${customerId}.${releaseHash}`);
    return await crypto.subtle.verify(
      "Ed25519",
      key,
      b64ToBytes(signature),
      signMessage
    );
  } catch {
    return false;
  }
}

export const Route = createFileRoute("/api/public/licence/manifest")({
  server: {
    handlers: {
      // Read-only verification: a client fetches the manifest it should be
      // running and compares hashes locally. No secrets are returned.
      GET: async ({ request }) => {
        const throttled = await enforceRateLimit(request, {
          limit: 30,
          windowSec: 60,
          bucket: "manifest_read",
          failMode: "open",
        });
        if (throttled) return throttled;

        const url = new URL(request.url);
        const buildId = url.searchParams.get("buildId")?.trim() ?? "";
        const customerId = url.searchParams.get("customerId")?.trim() || "universal";
        if (buildId.length < 4 || buildId.length > 200) {
          return json({ ok: false, error: "BAD_REQUEST" }, 400);
        }

        const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
        const { data, error } = await supabaseAdmin
          .from("release_manifests")
          .select("build_id, customer_id, asset_digest, signature, files, branch, published_at")
          .eq("build_id", buildId)
          .eq("customer_id", customerId)
          .maybeSingle();

        if (error || !data) return json({ ok: false, error: "NOT_FOUND" }, 404);

        return json({
          ok: true,
          manifest: {
            buildId: data.build_id,
            customerId: data.customer_id,
            assetDigest: data.asset_digest,
            signature: data.signature,
            files: data.files,
            branch: data.branch,
            publishedAt: data.published_at,
          },
        });
      },
      POST: async ({ request }) => {
        const throttled = await enforceRateLimit(request, {
          limit: 15,
          windowSec: 60,
          bucket: "manifest_upload",
          failMode: "closed",
        });
        if (throttled) return throttled;

        const secret = readEnv("RELEASE_MANIFEST_SECRET");
        const provided = request.headers.get("x-release-secret") ?? "";
        if (!secret || !timingSafeEqual(provided, secret)) {
          return json({ ok: false, error: "UNAUTHORIZED" }, 401);
        }
        try {
          const input = Schema.parse(await request.json());
          const targetHash = input.releaseHash || input.assetDigest;

          // Verify Ed25519 cryptographic signature before writing to database
          const validSignature = await verifyManifestSignature(
            input.buildId,
            input.customerId,
            targetHash,
            input.signature
          );

          if (!validSignature) {
            return json({ ok: false, error: "INVALID_MANIFEST_SIGNATURE" }, 400);
          }

          const { supabaseAdmin } = await import("@/integrations/supabase/client.server");
          const { error } = await supabaseAdmin
            .from("release_manifests")
            .upsert(
              {
                build_id: input.buildId,
                customer_id: input.customerId,
                asset_digest: targetHash,
                signature: input.signature,
                files: input.files,
                branch: input.branch,
                published_at: new Date().toISOString(),
              },
              { onConflict: "build_id" },
            );
          if (error) {
            console.error("[licence:manifest] Database insert error:", error);
            return json({ ok: false, error: "DATABASE_ERROR" }, 500);
          }
          return json({ ok: true, buildId: input.buildId, customerId: input.customerId });
        } catch (e) {
          console.error("[licence:manifest] Error:", e);
          return json({ ok: false, error: "BAD_REQUEST" }, 400);
        }
      },
    },
  },
});

import { createFileRoute } from "@tanstack/react-router";
import { z } from "zod";
import { refresh } from "@/lib/adapters/licence.server";
import { check } from "@/lib/adapters/ratelimit.server";
import { clientIp, json, serverDerivedOrigin } from "@/lib/licence-http";

const Schema = z.object({
  licenceKey: z.string().min(10).max(200),
  platform: z.enum(["mobile", "desktop"]),
  deviceSecret: z.string().min(16).max(200),
  buildId: z.string().max(200).optional(),
  assetDigest: z.string().max(200).optional(),
  deviceFingerprint: z.string().max(200).optional(),
  capabilityTier: z.string().max(32).optional(),
});

export const Route = createFileRoute("/api/public/licence/refresh")({
  server: {
    handlers: {
      OPTIONS: async ({ request }) => json({ ok: true }, 200, {}, request),
      POST: async ({ request }) => {
        let input: z.infer<typeof Schema>;
        try {
          input = Schema.parse(await request.json());
        } catch (e) {
          return json({ ok: false, error: e instanceof Error ? e.message : "BAD_REQUEST" }, 400, {}, request);
        }

        const ip = clientIp(request);
        const originHost = serverDerivedOrigin(request);

        // Refresh allocates nothing and every live viewer depends on it, so a
        // limiter outage fails OPEN here — but it is logged and the response
        // says so, rather than pretending the limit was enforced.
        const { allowed, degraded } = await check(
          `licence:refresh:${input.deviceSecret.slice(0, 24)}`,
          60,
          3600,
          { failMode: "open" },
        );
        if (!allowed) return json({ ok: false, error: "RATE_LIMITED" }, 429, {}, request, originHost);

        const result = await refresh({
          licenceKey: input.licenceKey,
          platform: input.platform,
          originHost,
          ip,
          userAgent: request.headers.get("user-agent"),
          attestation: { buildId: input.buildId, assetDigest: input.assetDigest },
          fingerprintSignal: input.deviceFingerprint ?? null,
          deviceSecret: input.deviceSecret,
          capabilityTier: input.capabilityTier ?? null,
        });

        if (!result.ok) return json({ ok: false, error: result.error }, result.status, {}, request, originHost);
        return json(
          {
            ok: true,
            token: result.token,
            plan: result.plan,
            features: result.features,
            expiresIn: result.expiresIn,
            graceHours: result.graceHours,
            deviceId: result.deviceId,
            limiterDegraded: degraded ?? false,
          },
          200,
          {},
          request,
          originHost,
        );
      },
    },
  },
});

/**
 * §4.4 — self-service device release. The client presses "release this device"
 * (or the vendor runs it during a handover) and the slot frees up after a 12h
 * cooldown. Possession of the device secret is required, so knowing the licence
 * key alone cannot evict somebody else's live device.
 */
import { createFileRoute } from "@tanstack/react-router";
import { z } from "zod";
import { releaseDevice } from "@/lib/adapters/licence.server";
import { check } from "@/lib/adapters/ratelimit.server";
import { clientIp, json } from "@/lib/licence-http";

const Schema = z.object({
  licenceKey: z.string().min(10).max(200),
  deviceSecret: z.string().min(16).max(200),
});

export const Route = createFileRoute("/api/public/licence/release")({
  server: {
    handlers: {
      OPTIONS: async ({ request }) => json({ ok: true }, 200, {}, request),
      POST: async ({ request }) => {
        let input: z.infer<typeof Schema>;
        try {
          input = Schema.parse(await request.json());
        } catch (e) {
          return json({ ok: false, error: e instanceof Error ? e.message : "BAD_REQUEST" }, 400, {}, request);
        }

        // Mutation → fail closed.
        const { allowed } = await check(`licence:release:${clientIp(request) ?? "unknown"}`, 5, 3600, {
          failMode: "closed",
        });
        if (!allowed) return json({ ok: false, error: "RATE_LIMITED" }, 429, {}, request);

        const result = await releaseDevice(input.licenceKey, input.deviceSecret);
        if (!result.ok) return json({ ok: false, error: result.error }, result.status, {}, request);
        return json({ ok: true, releaseAfter: result.releaseAfter }, 200, {}, request);
      },
    },
  },
});

/**
 * GET /api/public/licence/status
 * Non-sensitive public endpoint for client self-service diagnostics.
 * Returns license plan, expiry, active device slots, and status without
 * exposing private keys or database IDs.
 */
import { createFileRoute } from "@tanstack/react-router";
import { enforceRateLimit } from "@/lib/rate-limiter.middleware";
import { getLicenceStatus } from "@/lib/adapters/licence.server";

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: {
      "content-type": "application/json",
      "cache-control": "no-store",
    },
  });
}

export const Route = createFileRoute("/api/public/licence/status")({
  server: {
    handlers: {
      GET: async ({ request }) => {
        const throttled = await enforceRateLimit(request, {
          limit: 30,
          windowSec: 60,
          bucket: "licence_status",
          failMode: "open",
        });
        if (throttled) return throttled;

        const url = new URL(request.url);
        const licenceKey =
          url.searchParams.get("key") ||
          request.headers.get("x-licence-key") ||
          "";

        if (!licenceKey || licenceKey.length < 8) {
          return json({ ok: false, error: "MISSING_LICENCE_KEY" }, 400);
        }

        try {
          const result = await getLicenceStatus(licenceKey);
          if (!result.ok) {
            return json({ ok: false, error: result.error }, result.status);
          }
          return json(result, 200);
        } catch (e) {
          console.error("[licence:status] Internal error:", e);
          return json(
            { ok: false, error: "INTERNAL_ERROR" },
            500,
          );
        }
      },
    },
  },
});

