import {
  attachWebglRecovery,
  hasWebglSupport,
  WEBGL_UNSUPPORTED_MESSAGE,
} from "@/lib/webgl-recovery";
import {
  AR_STAGE_CLASS,
  applySceneHygiene,
  attachArViewportFit,
  detectDeviceTier,
  ensureArStageStyles,
  isImmersiveVrSupported,
